/* Transformation Name ==>SC_SFTR_TRANSACTIONS_LIVE ,Transformation Type ==>Target */

{{
	config(
		materialized='incremental',
		alias='SFTR_TRANSACTIONS_LIVE',
		schema='EMIR_SHARED',
		pre_hook ="",
		post_hook ="",
		incremental_strategy='append')
}}

With SQ_SC_RR_BNK_REPO_INV_FACTOut as (
	/* SubQuery from Source ==>SQ_SQ_SC_RR_BNK_REPO_INV_FACT */
/* transType: "Source" */
Select 
ACTION_TYPE,
PRODUCT,
BUSINESS_DATE,
BUSINESS_DATE_ID,
VERSION_ID,
BATCH_DETAILS_ID,
ENTITY_NAME,
ENTITY_LEI,
PRODUCT_TYPE,
PRODUCT_SUBTYPE,
CUSTODIAN,
CUSTODIAN_LEI,
CPARTY_REF,
CRESTID,
COUNTERPARTY_LEI,
COUNTERPARTY,
CURRENCY,
CURRENCY_ID,
ISIN,
CUSIP,
ISSUER,
ISSUER_LEI,
NOMINAL,
INITIAL_TRADE_PRICE,
CALCULATION_PRICE,
DIRTY_PRICE,
MARKET_VALUE,
REPO_INTEREST_RATE,
TRANSACTION_DATE_TIME,
REPO_START_DATE,
REPO_END_DATE,
TRANSACTION_START_AMOUNT,
TRANSACTION_RETURN_AMOUNT,
MONEY_BASIS,
HAIRCUT,
REPO_HAIRCUT_TYPE,
BOOK,
DEFAULT_STATUS,
ERROR_INDICATOR,
SECURITY_DIRECTION,
COUNTRY_CODE,
UTI,
MIC_CODE,
MASTER_AGREEMENT,
MASTER_AGREEMENT_VERSION,
UNDERLYING_PROUCT_TYPE,
SECURITY_CURRENCY,
TRADE_STATUS,
UPDATED_DATE,
ESCB_FLAG,
AMENDMENT_FLAG,
ENTERED_DATE_1,
TOTAL_CASH_FAIL_AMOUNT,
FLOAT_RATE,
FLOAT_RATE_REF_PERIOD,
FLOAT_RATE_PAY_FREQ,
SPREAD,
LAST_FLOAT_RATE_REFIX_DATE,
CURRENT_FLOAT_RATE,
MARKET_VALUE_BEFORE_FACTOR,
VAL_TRANS_HELD_AMT,
TOTAL_COLL_REQ_AMT,
MARGIN_AMOUNT,
TOTAL_EXPOS_AMT,
TRIPARTY_ISIN,
DBV_ISIN,
TRIPARTY_NOMINAL,
DBV_NOMINAL,
TRIPARTY_CURRENCY,
DBV_CURRENCY,
TRIPARTY_HAIRCUT,
DBV_HAIRCUT,
PRE_HC_MV_TX_CCY_AMT,
DBV_MARKET_VALUE,
TRIPARTY_MARKET_PRICE,
PRE_HC_MV_COLL_CCY_AMT,
TRD_CTRPTY_ESCB_FLAG,
TRADING_COUNTERPARTY_LEI,
PARENT_COUNTERPARTY,
TRD_CTRPTY_COUNTRY_CODE,
PARENT_COUNTRY_CODE,
COLLATERAL_CURRENCY,
ENTERED_DATE
 from 
(WITH 
 CURR_BATCH as (
 SELECT
    BATCH_BUSINESS_FROM_DATE
 FROM
    BATCH_MASTER
 WHERE  
  BATCH_FEED_INFO= 'SFTR_CALM_TRANSACTION_LIVE_LOAD_LTD' AND 
  BATCH_STATUS= 'I'),
 RECORD_SET as (
 SELECT
    RIF.*
 FROM
    RR_BNK_REPO_INV_FACT as RIF
 INNER JOIN 
  RR_TR_EXTRACTION_MODE as SPL_EXT_MODE
 ON
  SPL_EXT_MODE.SERVICE= 'CALM_LTD' AND 
  SPL_EXT_MODE.REGULATION= 'SFTR' AND 
  SPL_EXT_MODE.TR_EXTRACTION_MODE= 'NORMAL'
 INNER JOIN 
  CURR_BATCH
 ON
  RIF.BUSINESS_DATE= CURR_BATCH.BATCH_BUSINESS_FROM_DATE
 UNION ALL 
 SELECT
    RIF.*
 FROM
    RR_BNK_REPO_INV_FACT as RIF
 INNER JOIN 
  RR_TR_EXTRACTION_MODE as SPL_EXT_MODE
 ON
  SPL_EXT_MODE.SERVICE= 'CALM_LTD' AND 
  SPL_EXT_MODE.REGULATION= 'SFTR' AND 
  SPL_EXT_MODE.TR_EXTRACTION_MODE= 'ADHOC'
 INNER JOIN 
  RR_SFTR_TR_SPL_EXTRACTION_DATA as SPL_EXT_DATA
 ON
  SPL_EXT_DATA.SPL_MODE_RUN_ID= SPL_EXT_MODE.SPL_MODE_RUN_ID AND 
  RIF.BUSINESS_DATE= SPL_EXT_DATA.BUSINESS_DATE AND 
  SPL_EXT_DATA.ENTITY= SUBSTR((SELECT NAME FROM ENTITY_DIM WHERE ID = RIF.ENTITY_ID),5) AND 
  SPL_EXT_DATA.EXCHANGE= 'CALM' AND 
  SPL_EXT_DATA.REPORT_NAME= 'TRANSACTIONS' AND 
  SPL_EXT_DATA.COUNTERPARTY_LEI= RIF.COUNTERPARTY_LEI AND 
  SPL_EXT_DATA.UNIQUE_REFERENCE= RIF.UTI
 INNER JOIN 
  CURR_BATCH
 ON
  RIF.BUSINESS_DATE= CURR_BATCH.BATCH_BUSINESS_FROM_DATE)
 
 SELECT
    CASE
 WHEN(RIF.Entered_Date = RIF.Business_Date OR(RIF.BUSINESS_DATE = NVL((SELECT DATE_VALUE FROM application_variables WHERE variable_name = 'SFTR_TRANSACTIONS' AND string_value = 'SFTR_BACKLOADING_DATE'),TO_DATE('99991231','YYYYMMDD')) AND RIF.Entered_Date <(SELECT DATE_VALUE FROM application_variables WHERE variable_name = 'SFTR_TRANSACTIONS' AND string_value = 'SFTR_GO_LIVE_DATE'))) AND RIF.PRODUCT_TYPE IN('Repo','DBVRepo') AND RIF.Trade_Status  !=  'CANCELED' AND NVL(RIF.Amendment_Flag,'N/A') NOT IN('MODI','CORR') 
    THEN
    'NEWT' WHEN RIF.Entered_Date < RIF.Business_Date AND RIF.PRODUCT_TYPE IN('Repo','DBVRepo') AND RIF.Trade_Status  !=  'CANCELED' AND(RIF.Updated_Date < > RIF.Business_Date OR(RIF.Updated_Date = RIF.Business_Date AND RIF.AMENDMENT_FLAG IS NULL)) AND RIF.REPO_START_DATE <= RIF.Business_Date AND RIF.REPO_END_DATE  !=  RIF.Business_Date 
    THEN
    'COLU' WHEN RIF.Entered_Date <= RIF.Business_Date AND RIF.Updated_Date = RIF.Business_Date AND RIF.PRODUCT_TYPE IN('Repo','DBVRepo') AND RIF.Amendment_Flag = 'MODI' 
    THEN
    'MODI' WHEN RIF.Entered_Date < RIF.Business_Date AND RIF.Updated_Date = RIF.Business_Date AND RIF.PRODUCT_TYPE IN('Repo','DBVRepo') AND RIF.Amendment_Flag = 'ETRM' AND RIF.Trade_Status  !=  'CANCELED' OR(RIF.Entered_Date < RIF.Business_Date AND RIF.Updated_Date = RIF.Business_Date AND RIF.PRODUCT_TYPE IN('Repo','DBVRepo') AND RIF.TRADE_STATUS = 'DEFAULTED' AND TCD.IS_DEFAULTED = 'DEFAULTED' AND TCD.DEFAULTED_DATE = RIF.Business_Date AND RIF.REPO_START_DATE <= RIF.Business_Date) 
    THEN
    'ETRM' WHEN RIF.Entered_Date <= RIF.Business_Date AND RIF.Updated_Date = RIF.Business_Date AND RIF.PRODUCT_TYPE IN('Repo','DBVRepo') AND RIF.Amendment_Flag = 'CORR' 
    THEN
    'CORR' WHEN RIF.Entered_Date < RIF.Business_Date AND RIF.Updated_Date = RIF.Business_Date AND RIF.PRODUCT_TYPE IN('Repo','DBVRepo') AND RIF.Trade_Status = 'CANCELED' AND NVL(RIF.Amendment_Flag,'N/A') NOT IN('MODI','CORR') OR(RIF.Entered_Date < RIF.Business_Date AND RIF.Updated_Date = RIF.Business_Date AND RIF.PRODUCT_TYPE IN('Repo','DBVRepo') AND RIF.TRADE_STATUS = 'DEFAULTED' AND TCD.IS_DEFAULTED = 'DEFAULTED' AND TCD.DEFAULTED_DATE = RIF.Business_Date AND RIF.REPO_START_DATE > RIF.Business_Date) 
    THEN
    'EROR' 
    ELSE
    NULL END as ACTION_TYPE,
    CASE
 WHEN RIF.PRODUCT_TYPE = 'Repo' AND PRODUCT_SUBTYPE = 'Standard' 
    THEN
    'STANDARD' WHEN RIF.PRODUCT_TYPE = 'Repo' AND PRODUCT_SUBTYPE = 'Triparty' 
    THEN
    'TRIPARTY' WHEN RIF.PRODUCT_TYPE = 'DBVRepo' 
    THEN
    'DBV' 
    ELSE
    NULL END as PRODUCT,
    RIF.BUSINESS_DATE,
    ED.NAME as ENTITY,
    ED.LEGAL_ENTITY_IDENTIFIER as ENTITY_LEI,
    RIF.PRODUCT_TYPE,
    RIF.PRODUCT_SUBTYPE,
    RIF.CUSTODIAN_LEI,
    RIF.COUNTERPARTY_LEI,
    RIF.COUNTERPARTY,
    RIF.CURRENCY,
    RIF.ISIN,
    RIF.ISSUER,
    RIF.NOMINAL as NOMINAL,
    RIF.DIRTY_PRICE as DIRTY_PRICE,
    RIF.REPO_INTEREST_RATE as REPO_INTEREST_RATE,
    RIF.TRANSACTION_DATE_TIME,
    RIF.REPO_START_DATE,
    RIF.REPO_END_DATE,
    RIF.TRANSACTION_START_AMOUNT as TRANSACTION_START_AMOUNT,
    RIF.TRANSACTION_RETURN_AMOUNT as TRANSACTION_RETURN_AMOUNT,
    RIF.MONEY_BASIS,
    RIF.HAIRCUT,
    RIF.SECURITY_DIRECTION,
    RIF.COUNTRY_CODE,
    RIF.UTI,
    RIF.MIC_CODE,
    RIF.MASTER_AGREEMENT,
    RIF.MASTER_AGREEMENT_VERSION,
    RIF.TOTAL_CASH_FAIL_AMOUNT,
    RIF.FLOAT_RATE,
    RIF.FLOAT_RATE_REF_PERIOD,
    RIF.FLOAT_RATE_PAY_FREQ,
    RIF.SPREAD,
    RIF.LAST_FLOAT_RATE_REFIX_DATE,
    RIF.CURRENT_FLOAT_RATE,
    RIF.MARKET_VALUE_BEFORE_FACTOR as MARKET_VALUE_BEFORE_FACTOR,
    TRIPARTY.ISIN as TRIPARTY_ISIN,
    DBV.ISIN as DBV_ISIN,
    TRIPARTY.NOMINAL as TRIPARTY_NOMINAL,
    DBV.NOMINAL as DBV_NOMINAL,
    TRIPARTY.CURRENCY as TRIPARTY_CURRENCY,
    DBV.CURRENCY as DBV_CURRENCY,
    TRIPARTY.HAIRCUT as TRIPARTY_HAIRCUT,
    TRIPARTY.PRE_HC_MV_TX_CCY_AMT,
    DBV.MARKET_VALUE as DBV_MARKET_VALUE,
    TRIPARTY.MARKET_PRICE as TRIPARTY_MARKET_PRICE,
    TRIPARTY.PRE_HC_MV_COLL_CCY_AMT as PRE_HC_MV_COLL_CCY_AMT,
    TCD.ESCB_FLAG,
    TCD.TRADING_COUNTERPARTY_LEI,
    TCD.PARENT_COUNTERPARTY,
    TCD.COUNTRY_CODE,
    TCD.PARENT_COUNTRY_CODE,
    RIF.COLLATERAL_CURRENCY,
    RIF.ENTERED_DATE
 FROM
    RECORD_SET as RIF
 INNER JOIN 
  CURR_BATCH
 ON
  RIF.BUSINESS_DATE= CURR_BATCH.BATCH_BUSINESS_FROM_DATE
 LEFT OUTER JOIN 
  RR_BNK_TRIPTYALC_INVST_FACT as TRIPARTY
 ON
  RIF.TRANS_ID= TRIPARTY.TRANS_ID AND 
  RIF.BUSINESS_DATE= TRIPARTY.BUSINESS_DATE AND 
  RIF.ENTITY_ID= TRIPARTY.ENTITY_ID AND 
  UPPER(TRIPARTY.ISIN) NOT LIKE 'CASHCOLLATRL%'
 LEFT OUTER JOIN 
  RR_BNK_DBV_ALLCTN_INV_FACT as DBV
 ON
  RIF.TRANS_ID= DBV.TRANS_ID AND 
  RIF.BUSINESS_DATE= DBV.BUSINESS_DATE AND 
  RIF.ENTITY_ID= DBV.ENTITY_ID
 INNER JOIN 
  ENTITY_DIM as ED
 ON
  RIF.ENTITY_ID= ED.ID AND 
  ED.NAME= '{{ var("ENTITY") }}'
 LEFT OUTER JOIN 
  DW_MART.TRADING_COUNTERPARTIES_DIM as TCD
 ON
  TCD.TRADING_COUNTERPARTY= RIF.COUNTERPARTY AND 
  CURR_BATCH.BATCH_BUSINESS_FROM_DATE >= TCD.EFFECTIVE_FROM_DATE AND 
  CURR_BATCH.BATCH_BUSINESS_FROM_DATE < NVL(TCD.EFFECTIVE_TO_DATE,TO_DATE('31-DEC-2099','DD-MON-YYYY'))
 WHERE  
  ((NVL(TCD.IS_DEFAULTED,'ACTIVE')= 'DEFAULTED' AND TCD.DEFAULTED_DATE = RIF.BUSINESS_DATE) OR NVL(TCD.IS_DEFAULTED,'ACTIVE') = 'ACTIVE') AND 
  (((SELECT NVL(STRING_VALUE2,'N') FROM APPLICATION_VARIABLES WHERE VARIABLE_NAME= 'SFTR_TRANSACTIONS' AND STRING_VALUE = 'SFTR_BACK_LOADING_FLAG') = 'N' AND RIF.ENTERED_DATE >=(SELECT DATE_VALUE FROM APPLICATION_VARIABLES WHERE VARIABLE_NAME = 'SFTR_TRANSACTIONS' AND STRING_VALUE = 'SFTR_GO_LIVE_DATE')) OR((SELECT NVL(STRING_VALUE2,'N') FROM APPLICATION_VARIABLES WHERE VARIABLE_NAME = 'SFTR_TRANSACTIONS' AND STRING_VALUE = 'SFTR_BACK_LOADING_FLAG') = 'Y')) AND 
   RIF.UTI NOT IN
 (SELECT
 distinct
    RR_BNK_REPO_INV_FACT.UTI
 FROM
    RR_BNK_REPO_INV_FACT
 WHERE  
  BUSINESS_DATE= TO_DATE('{{ var("BUSINESS_DATE") }}','YYYYMMDD') AND 
  TRADE_STATUS= 'CANCELED' AND 
   ENTERED_DATE <
 (SELECT
    DATE_VALUE
 FROM
    APPLICATION_VARIABLES
 WHERE  
  VARIABLE_NAME= 'SFTR_TRANSACTIONS' AND 
  STRING_VALUE= 'SFTR_GO_LIVE_DATE') AND 
   ENTITY_ID =
 (SELECT
 distinct
    ID
 FROM
    ENTITY_DIM
 WHERE  
  NAME= '{{ var("ENTITY") }}' AND 
  TO_DATE('{{ var("BUSINESS_DATE") }}','YYYYMMDD') BETWEEN EFFECTIVE_DATE AND 
  NVL(EXPIRATION_DATE,TO_DATE('20991231','YYYYMMDD')))) AND 
  (TCD.ESCB_FLAG IS NULL OR TCD.ESCB_FLAG= 'N') AND 
  (((RIF.ENTERED_DATE= RIF.BUSINESS_DATE OR(RIF.BUSINESS_DATE =(SELECT DATE_VALUE FROM APPLICATION_VARIABLES WHERE VARIABLE_NAME = 'SFTR_TRANSACTIONS' AND STRING_VALUE = 'SFTR_BACKLOADING_DATE') AND RIF.ENTERED_DATE <(SELECT DATE_VALUE FROM APPLICATION_VARIABLES WHERE VARIABLE_NAME = 'SFTR_TRANSACTIONS' AND STRING_VALUE = 'SFTR_GO_LIVE_DATE'))) AND RIF.PRODUCT_TYPE IN('REPO','DBVREPO') AND RIF.TRADE_STATUS  !=  'CANCELED' AND NVL(RIF.AMENDMENT_FLAG,'N/A') NOT IN('MODI','CORR')) OR(RIF.ENTERED_DATE <= RIF.BUSINESS_DATE AND RIF.PRODUCT_TYPE IN('REPO','DBVREPO') AND RIF.TRADE_STATUS  !=  'CANCELED' AND(RIF.UPDATED_DATE < > RIF.BUSINESS_DATE OR(RIF.UPDATED_DATE = RIF.BUSINESS_DATE AND RIF.AMENDMENT_FLAG IS NULL)) AND RIF.REPO_START_DATE <= RIF.BUSINESS_DATE AND RIF.REPO_END_DATE  !=  RIF.BUSINESS_DATE) OR(RIF.ENTERED_DATE <= RIF.BUSINESS_DATE AND RIF.UPDATED_DATE = RIF.BUSINESS_DATE AND RIF.PRODUCT_TYPE IN('REPO','DBVREPO') AND NVL(RIF.AMENDMENT_FLAG,'N/A') = 'MODI' AND RIF.TRADE_STATUS  !=  'CANCELED') OR(RIF.ENTERED_DATE < RIF.BUSINESS_DATE AND RIF.UPDATED_DATE = RIF.BUSINESS_DATE AND RIF.PRODUCT_TYPE IN('REPO','DBVREPO') AND NVL(RIF.AMENDMENT_FLAG,'N/A') = 'ETRM' AND RIF.TRADE_STATUS  !=  'CANCELED') OR(RIF.ENTERED_DATE <= RIF.BUSINESS_DATE AND RIF.UPDATED_DATE = RIF.BUSINESS_DATE AND RIF.PRODUCT_TYPE IN('REPO','DBVREPO') AND NVL(RIF.AMENDMENT_FLAG,'N/A') = 'CORR' AND RIF.TRADE_STATUS  !=  'CANCELED') OR(RIF.ENTERED_DATE < RIF.BUSINESS_DATE AND RIF.UPDATED_DATE = RIF.BUSINESS_DATE AND RIF.PRODUCT_TYPE IN('REPO','DBVREPO') AND RIF.TRADE_STATUS = 'CANCELED' AND NVL(RIF.AMENDMENT_FLAG,'N/A') NOT IN('MODI','CORR')) OR(RIF.ENTERED_DATE < RIF.BUSINESS_DATE AND RIF.UPDATED_DATE = RIF.BUSINESS_DATE AND RIF.PRODUCT_TYPE IN('REPO','DBVREPO') AND RIF.TRADE_STATUS = 'DEFAULTED' AND TCD.IS_DEFAULTED = 'DEFAULTED' AND TCD.DEFAULTED_DATE = RIF.BUSINESS_DATE AND RIF.REPO_START_DATE <= RIF.BUSINESS_DATE) OR(RIF.ENTERED_DATE < RIF.BUSINESS_DATE AND RIF.UPDATED_DATE = RIF.BUSINESS_DATE AND RIF.PRODUCT_TYPE IN('REPO','DBVREPO') AND RIF.TRADE_STATUS = 'DEFAULTED' AND TCD.IS_DEFAULTED = 'DEFAULTED' AND TCD.DEFAULTED_DATE = RIF.BUSINESS_DATE AND RIF.REPO_START_DATE > RIF.BUSINESS_DATE)))
 ),

RCL_BOND_STATICOut as (
	/* transType: "LookupSource" */
Select LEI, 
		BUSINESS_DATE, 
		ENTITY, 
		ISIN, 
		in_BUSINESS_DATE, 
		in_ENTITY, 
		in_ISIN
 from 
{{ source ('LKP_RCL_BOND_STATIC_GET_LEI_1','RCL_BOND_STATIC') }}
 ),

exp_CONSOLIDATE_ISINOut as (
	/* transType: "Expression" */
Select 
	( CASE WHEN PRODUCT_TYPE = 'Repo' AND PRODUCT_SUBTYPE = 'Standard' THEN ISIN ELSE ( CASE WHEN PRODUCT_TYPE = 'Repo' AND PRODUCT_SUBTYPE = 'Triparty' THEN TRIPARTY_ISIN ELSE ( CASE WHEN PRODUCT_TYPE = 'DBVRepo' THEN DBV_ISIN ELSE NULL END ) END ) END ) as o_CONSOLIDATED_ISIN
From SQ_SC_RR_BNK_REPO_INV_FACTOut as SQ_SC_RR_BNK_REPO_INV_FACTOut),

DSR_EXPTRANSOut as (
	/* transType: "Expression" */
Select 
	SQ_SC_RR_BNK_REPO_INV_FACTOut.BUSINESS_DATE as in_BUSINESS_DATE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.UTI as in_UTI,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.ACTION_TYPE as in_ACTION_TYPE
From SQ_SC_RR_BNK_REPO_INV_FACTOut as SQ_SC_RR_BNK_REPO_INV_FACTOut),

LKP_RCL_BOND_STATICOut as (
	/* transType: "Lookup Procedure" */
Select 
	SFTR_COLL_ISSUER_JURISDICTION as SFTR_COLL_ISSUER_JURISDICTION,
	 SFTR_ISSUER_JURISDICTION as SFTR_ISSUER_JURISDICTION,
	 COUNTRY_OF_JURISDICTION as COUNTRY_OF_JURISDICTION,
	 STRING_VALUE3 as STRING_VALUE3,
	 exp_CONSOLIDATE_ISINOut.i_ISIN as i_ISIN_1,
	 exp_CONSOLIDATE_ISIN.o_CONSOLIDATED_ISIN AS i_ISIN_2 
FROM
	exp_CONSOLIDATE_ISINOut as exp_CONSOLIDATE_ISINOut 
 LEFT JOIN  ( select * from (
select 
*,ISIN,row_number() over(partition by ISIN order by rnk_fst desc nulls last) as rnk_lst
from
(
select *,ISIN,row_number() over(partition by ISIN order by ISIN nulls last) as rnk_fst
from ( SELECT
       SFTR_COLL_ISSUER_JURISDICTION as SFTR_COLL_ISSUER_JURISDICTION,
       SFTR_ISSUER_JURISDICTION as SFTR_ISSUER_JURISDICTION,
       T1.COUNTRY_OF_JURISDICTION as COUNTRY_OF_JURISDICTION,
       STRING_VALUE3 as STRING_VALUE3,
       T1.ISIN as ISIN
 FROM
       RCL_BOND_STATIC as T1
 LEFT JOIN 
    APPLICATION_VARIABLES as T2
  ON
   T2.VARIABLE_NAME= 'SFTR_TRANSACTIONS_STATIC' AND 
   T2.STRING_VALUE= 'COLL_ISSUER_JURISDICTION' AND 
   ACTIVE_Y_N= 'Y' AND 
   T2.STRING_VALUE2= T1.BLOOMBERG_TICKER
 WHERE   
   BUSINESS_DATE= TO_DATE('{{ var("BUSINESS_DATE") }}','YYYYMMDD') AND  
   T1.ENTITY= 'LCH.LTD' )
) lkp_inner
) lkp_outer
where rnk_lst=1 ) 
ON
	ISIN = i_ISIN
 
),

EXPTRANSOut as (
	/* transType: "Expression" */
Select 
	in_BUSINESS_DATE as in_BUSINESS_DATE,
	 in_UTI as in_UTI,
	 in_ACTION_TYPE as in_ACTION_TYPE,
	 dsf_1.ACTION_TYPE as v_ACTION_TYPE_ADHOC,
	 ( CASE WHEN '{{ var("EMIR_TR_EXTRACTION_MODE") }}' = 'ADHOC' AND v_ACTION_TYPE_ADHOC IS NOT NULL THEN v_ACTION_TYPE_ADHOC ELSE in_ACTION_TYPE END ) as v_ACTION_TYPE,
	 v_ACTION_TYPE as o_ACTION_TYPE
From DSR_EXPTRANSOut as DSR_EXPTRANSOut
LEFT JOIN (
SELECT ACTION_TYPE, BUSINESS_DATE, REPORT_NAME, ENTITY, UNIQUE_REFERENCE FROM (  SELECT ACTION_TYPE, BUSINESS_DATE, REPORT_NAME, ENTITY, UNIQUE_REFERENCE,  ROW_NUMBER() OVER (PARTITION BY BUSINESS_DATE, REPORT_NAME, ENTITY, UNIQUE_REFERENCE ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT ACTION_TYPE, BUSINESS_DATE, REPORT_NAME, ENTITY, UNIQUE_REFERENCE,  ROW_NUMBER() OVER (PARTITION BY BUSINESS_DATE, REPORT_NAME, ENTITY, UNIQUE_REFERENCE ORDER BY BUSINESS_DATE, REPORT_NAME, ENTITY, UNIQUE_REFERENCE NULLS LAST) AS rnk_fst   FROM ( SELECT    SPL_EXT_DATA.ACTION_TYPE as ACTION_TYPE,    SPL_EXT_DATA.SPL_MODE_RUN_ID as SPL_MODE_RUN_ID,    SPL_EXT_DATA.RCL_SERVICE as RCL_SERVICE,    SPL_EXT_DATA.EXCHANGE as EXCHANGE,    SPL_EXT_DATA.MEMBER_MNEMONIC as MEMBER_MNEMONIC,    SPL_EXT_DATA.BUSINESS_DATE as BUSINESS_DATE,    SPL_EXT_DATA.REPORT_NAME as REPORT_NAME,    SPL_EXT_DATA.ENTITY as ENTITY,    SPL_EXT_DATA.UNIQUE_REFERENCE as UNIQUE_REFERENCE FROM    RR_TR_EXTRACTION_MODE as SPL_EXT_MODE INNER JOIN   RR_SFTR_TR_SPL_EXTRACTION_DATA as SPL_EXT_DATA  ON  SPL_EXT_DATA.SPL_MODE_RUN_ID= SPL_EXT_MODE.SPL_MODE_RUN_ID WHERE    SPL_EXT_MODE.SERVICE= 'CALM_LTD' AND   SPL_EXT_MODE.REGULATION= 'SFTR' AND   SPL_EXT_MODE.TR_EXTRACTION_MODE= 'ADHOC' )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.BUSINESS_DATE = in_BUSINESS_DATE AND dsf_1.REPORT_NAME = 'TRANSACTIONS' AND dsf_1.ENTITY = 'LTD' AND dsf_1.UNIQUE_REFERENCE = in_UTI
),

EXPTRANS_details as (
  Select
  	EXPTRANSOut.o_ACTION_TYPE as ACTION_TYPE
  From EXPTRANSOut as EXPTRANSOut
),

SQ_SC_RR_BNK_REPO_INV_FACT_details as (
  Select
  	SQ_SC_RR_BNK_REPO_INV_FACTOut.PRODUCT as PRODUCT,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.BUSINESS_DATE as BUSINESS_DATE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.COUNTERPARTY_LEI as OTHER_PARTY,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.COUNTERPARTY as COUNTERPARTY,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.SECURITY_DIRECTION as SECURITY_DIRECTION,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.COUNTRY_CODE as COUNTRY_CODE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.CUSTODIAN_LEI as CUSTODIAN_LEI,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.PRODUCT_TYPE as PRODUCT_TYPE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.PRODUCT_SUBTYPE as PRODUCT_SUBTYPE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.UTI as UTI,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.MIC_CODE as MIC_CODE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.MASTER_AGREEMENT as MASTER_AGREEMENT,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.MASTER_AGREEMENT_VERSION as MASTER_AGREEMENT_VERSION,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.TRANSACTION_DATE_TIME as TRANSACTION_DATE_TIME,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.REPO_START_DATE as REPO_START_DATE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.REPO_END_DATE as REPO_END_DATE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.REPO_INTEREST_RATE as REPO_INTEREST_RATE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.FLOAT_RATE as FLOAT_RATE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.FLOAT_RATE_REF_PERIOD as FLOAT_RATE_REF_PERIOD,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.FLOAT_RATE_PAY_FREQ as FLOAT_RATE_PAY_FREQ,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.SPREAD as SPREAD,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut.CURRENT_FLOAT_RATE as CURRENT_FLOAT_RATE,
