	 SQ_SC_RR_BNK_REPO_INV_FACTOut2.ENTITY_LEI as REPORTING_COUNTERPARTY,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut2.ENTITY_LEI as ENTITY_LEI,
	 LKP_RCL_BOND_STATICOut.SFTR_COLL_ISSUER_JURISDICTION as SFTR_COLL_ISSUER_JURISDICTION,
	 LKP_RCL_BOND_STATICOut.SFTR_ISSUER_JURISDICTION as SFTR_ISSUER_JURISDICTION,
	 LKP_RCL_BOND_STATICOut.COUNTRY_OF_JURISDICTION as COUNTRY_OF_JURISDICTION,
	 LKP_RCL_BOND_STATICOut.STRING_VALUE3 as STRING_VALUE3,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut2.PRE_HC_MV_COLL_CCY_AMT as PRE_HC_MV_COLL_CCY_AMT1,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut2.TRD_CTRPTY_ESCB_FLAG as TRD_CTRPTY_ESCB_FLAG,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut2.TRADING_COUNTERPARTY_LEI as TRADING_COUNTERPARTY_LEI,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut2.PARENT_COUNTERPARTY as PARENT_COUNTERPARTY,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut2.TRD_CTRPTY_COUNTRY_CODE as TRD_CTRPTY_COUNTRY_CODE,
	 SQ_SC_RR_BNK_REPO_INV_FACTOut2.PARENT_COUNTRY_CODE as PARENT_COUNTRY_CODE,
	 ROW_NUMBER ( ) OVER ( ORDER BY 1 ) as jkey 
From
LKP_RCL_BOND_STATICOut as LKP_RCL_BOND_STATICOut INNER JOIN EXPTRANS_details as EXPTRANS_details 
ON
LKP_RCL_BOND_STATICOut.jkey = EXPTRANS_details.jkey
 INNER JOIN SQ_SC_RR_BNK_REPO_INV_FACTOut2 as SQ_SC_RR_BNK_REPO_INV_FACTOut2 
ON
LKP_RCL_BOND_STATICOut.jkey = SQ_SC_RR_BNK_REPO_INV_FACTOut2.jkey
 
),

EXP_FORMATOut as (
	/* transType: "Expression" */
Select 
	ACTION_TYPE as ACTION_TYPE,
	 PRODUCT as PRODUCT,
	 BUSINESS_DATE as BUSINESS_DATE,
	 OTHER_PARTY as OTHER_PARTY,
	 COUNTERPARTY as COUNTERPARTY,
	 SECURITY_DIRECTION as SECURITY_DIRECTION,
	 COUNTRY_CODE as COUNTRY_CODE,
	 CUSTODIAN_LEI as CUSTODIAN_LEI,
	 PRODUCT_TYPE as PRODUCT_TYPE,
	 PRODUCT_SUBTYPE as PRODUCT_SUBTYPE,
	 UTI as UTI,
	 MIC_CODE as MIC_CODE,
	 MASTER_AGREEMENT as MASTER_AGREEMENT,
	 MASTER_AGREEMENT_VERSION as MASTER_AGREEMENT_VERSION,
	 TRANSACTION_DATE_TIME as TRANSACTION_DATE_TIME,
	 REPO_START_DATE as REPO_START_DATE,
	 REPO_END_DATE as REPO_END_DATE,
	 REPO_INTEREST_RATE as REPO_INTEREST_RATE,
	 FLOAT_RATE as FLOAT_RATE,
	 FLOAT_RATE_REF_PERIOD as FLOAT_RATE_REF_PERIOD,
	 FLOAT_RATE_PAY_FREQ as FLOAT_RATE_PAY_FREQ,
	 SPREAD as SPREAD,
	 CURRENT_FLOAT_RATE as CURRENT_FLOAT_RATE,
	 LAST_FLOAT_RATE_REFIX_DATE as LAST_FLOAT_RATE_REFIX_DATE,
	 TRANSACTION_START_AMOUNT as TRANSACTION_START_AMOUNT,
	 TRANSACTION_RETURN_AMOUNT as TRANSACTION_RETURN_AMOUNT,
	 CURRENCY as CURRENCY,
	 TOTAL_CASH_FAIL_AMOUNT as TOTAL_CASH_FAIL_AMOUNT,
	 ( CASE WHEN TOTAL_CASH_FAIL_AMOUNT IS NULL THEN 0 ELSE TOTAL_CASH_FAIL_AMOUNT END ) as v_TOTAL_CASH_FAIL_AMOUNT,
	 ISIN as ISIN,
	 NOMINAL as NOMINAL,
	 HAIRCUT as HAIRCUT,
	 TRIPARTY_ISIN as TRIPARTY_ISIN,
	 DBV_ISIN as DBV_ISIN,
	 TRIPARTY_NOMINAL as TRIPARTY_NOMINAL,
	 DBV_NOMINAL as DBV_NOMINAL,
	 TRIPARTY_CURRENCY as TRIPARTY_CURRENCY,
	 DBV_CURRENCY as DBV_CURRENCY,
	 TRIPARTY_HAIRCUT as TRIPARTY_HAIRCUT,
	 PRE_HC_MV_TX_CCY_AMT as PRE_HC_MV_TX_CCY_AMT,
	 DBV_MARKET_VALUE as DBV_MARKET_VALUE,
	 DIRTY_PRICE as DIRTY_PRICE,
	 TRIPARTY_MARKET_PRICE as TRIPARTY_MARKET_PRICE,
	 MARKET_VALUE_BEFORE_FACTOR as MARKET_VALUE_BEFORE_FACTOR,
	 PRE_HC_MV_COLL_CCY_AMT as PRE_HC_MV_COLL_CCY_AMT,
	 COLLATERAL_CURRENCY as COLLATERAL_CURRENCY,
	 ENTERED_DATE as ENTERED_DATE,
	 GENERATED_SEQ as GENERATED_SEQ,
	 LPAD ( GENERATED_SEQ,
	 9,
	 '0' ) as v_SEQ_LPAD_TO_9,
	 DATEDIFF ( SECOND,
	 TO_TIMESTAMP ( '01/01/1970 00:00:00',
	 'DD-MM-YYYY HH24:MI:SS' ),
	 CURRENT_TIMESTAMP ) as v_EPOC_TIME,
	 v_EPOC_TIME || v_SEQ_LPAD_TO_9 as v_CONCATE_ID,
	 v_CONCATE_ID as ID,
	 ENTITY as ENTITY,
	 SUBMITTING_ENTITY as SUBMITTING_ENTITY,
	 REPORTING_COUNTERPARTY as REPORTING_COUNTERPARTY,
	 ENTITY_LEI as ENTITY_LEI,
	 ENTITY_LEI as RESPONSIBLE_ENTITY,
	 'F' as REPORTING_PARTY_NATURE,
	 'CCPS' as REPORTING_PARTY_SECTOR,
	 ( CASE WHEN ACTION_TYPE = 'ETRM' OR ACTION_TYPE = 'EROR' OR ACTION_TYPE = 'COLU' THEN NULL ELSE ( CASE WHEN SECURITY_DIRECTION = 'OUT' THEN 'GIVE' ELSE ( CASE WHEN SECURITY_DIRECTION = 'IN' THEN 'TAKE' ELSE NULL END ) END ) END ) as COUNTERPARTY_SIDE,
	 'L' as OTHER_PARTY_ID_TYPE,
	 ( CASE WHEN ACTION_TYPE = 'ETRM' OR ACTION_TYPE = 'EROR' THEN NULL ELSE ( CASE WHEN PRODUCT_SUBTYPE = 'Triparty' OR PRODUCT_TYPE = 'DBVRepo' THEN CUSTODIAN_LEI ELSE NULL END ) END ) as TRIPARTY_AGENT,
	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' THEN ( CASE WHEN PRODUCT_TYPE = 'DBVRepo' OR ( PRODUCT_TYPE = 'Repo' AND PRODUCT_SUBTYPE = 'Triparty' ) THEN CUSTODIAN_LEI ELSE NULL END ) ELSE NULL END ) as v_CSD_OR_INDIRECT,
	 v_CSD_OR_INDIRECT as CSD_OR_INDIRECT,
	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' THEN ( CASE WHEN v_CSD_OR_INDIRECT IS NOT NULL OR v_CSD_OR_INDIRECT != '' THEN 'I' ELSE NULL END ) ELSE NULL END ) as CSD_OR_INDIRECT_TYPE,
	 dsf_1.UPDATED_DATE as v_UPDATED_DATE_lkp,
	 ( CASE WHEN ACTION_TYPE = 'EROR' THEN NULL ELSE ( CASE WHEN ACTION_TYPE = 'CORR' THEN ( CASE WHEN v_UPDATED_DATE_lkp IS NULL THEN ENTERED_DATE ELSE v_UPDATED_DATE_lkp END ) ELSE BUSINESS_DATE END ) END ) as v_EVENT_DATE,
	 v_EVENT_DATE as EVENT_DATE,
	 ( CASE WHEN ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'MODI' AND ACTION_TYPE != 'CORR' AND ACTION_TYPE != 'COLU' THEN NULL ELSE ( CASE WHEN PRODUCT_TYPE = 'DBVRepo' OR PRODUCT_TYPE = 'Repo' THEN 'REPO' ELSE NULL END ) END ) as TYPE_OF_SFT,
	 ( CASE WHEN ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'MODI' AND ACTION_TYPE != 'CORR' THEN NULL ELSE 'false' END ) as CLEARED,
	 ( CASE WHEN ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'CORR' AND ACTION_TYPE != 'MODI' THEN NULL ELSE MIC_CODE END ) as TRADING_VENUE,
	 ( CASE WHEN ACTION_TYPE = 'ETRM' OR ACTION_TYPE = 'EROR' THEN NULL ELSE ( CASE WHEN dsf_2.STRING_VALUE3 IS NULL THEN 'OTHR' ELSE dsf_2.STRING_VALUE3 END ) END ) as v_MASTER_AGREEMENT_TYPE,
	 v_MASTER_AGREEMENT_TYPE as MASTER_AGREEMENT_TYPE,
	 ( CASE WHEN ACTION_TYPE = 'ETRM' OR ACTION_TYPE = 'EROR' THEN NULL ELSE 'C' END ) as MASTER_AGREEMENT_TYPE_ID,
	 ( CASE WHEN ACTION_TYPE = 'ETRM' OR ACTION_TYPE = 'EROR' OR v_MASTER_AGREEMENT_TYPE = 'OTHR' THEN NULL ELSE MASTER_AGREEMENT_VERSION END ) as O_MASTER_AGREEMENT_VERSION,
	 TO_VARCHAR ( TRANSACTION_DATE_TIME,
	 'YYYY' ) as v_TRANSACTION_YEAR,
	 dsf_3.BST_APPLICABLE as v_BST_FLAG,
	 ( CASE WHEN v_BST_FLAG = 'Y' THEN DATEADD ( '-1',
	 'HH24',
	 TRANSACTION_DATE_TIME ) ELSE TRANSACTION_DATE_TIME END ) as v_TRANSACTION_DATE_TIME,
	 IFF ( ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'CORR' OR ACTION_TYPE = 'MODI',
	 ( CASE WHEN v_TRANSACTION_DATE_TIME IS NULL THEN NULL ELSE TO_VARCHAR ( v_TRANSACTION_DATE_TIME,
	 'YYYY-MM-DD' ) || 'T' || TO_VARCHAR ( v_TRANSACTION_DATE_TIME,
	 'HH24:MI:SS' ) || 'Z' END ),
	 NULL ) as EXECUTION_TIMESTAMP,
	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' THEN REPO_START_DATE ELSE NULL END ) as VALUE_DATE,
	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' THEN REPO_END_DATE ELSE NULL END ) as MATURITY_DATE,
	 ( CASE WHEN ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'MODI' AND ACTION_TYPE != 'CORR' THEN NULL ELSE ( CASE WHEN ( PRODUCT_TYPE = 'Repo' AND PRODUCT_SUBTYPE = 'Triparty' ) OR PRODUCT_TYPE = 'DBVRepo' THEN 'GENE' ELSE 'SPEC' END ) END ) as GENERAL_COLLATERAL_INDICATOR,
	 ( CASE WHEN ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'MODI' AND ACTION_TYPE != 'CORR' THEN NULL ELSE ( CASE WHEN PRODUCT_TYPE = 'DBVRepo' THEN 'TRUE' ELSE 'FALSE' END ) END ) as DBV_INDICATOR,
	 ( CASE WHEN ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'MODI' AND ACTION_TYPE != 'CORR' THEN NULL ELSE 'TTCA' END ) as COLLATERAL_METHOD,
	 ( CASE WHEN ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'MODI' AND ACTION_TYPE != 'CORR' THEN NULL ELSE 'false' END ) as OPEN_TERM,
	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' THEN 'NOAP' ELSE NULL END ) as TERM_OPTIONALITY,
	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' THEN 'Fxd' ELSE NULL END ) as INTEREST_RATE_DIRECTION,
	 ROUND ( ROUND ( REPO_INTEREST_RATE,
	 ( CASE WHEN 11 - LENGTH ( DATE_TRUNC ( 'DAY',
	 ABS ( REPO_INTEREST_RATE ) ) ) < 0 THEN 1 ELSE 11 - LENGTH ( DATE_TRUNC ( 'DAY',
	 ABS ( REPO_INTEREST_RATE ) ) ) END ) ),
	 10 ) as v_DYNM_REPO_INTEREST_RATE,
	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' THEN ( CASE WHEN FLOAT_RATE IS NOT NULL THEN NULL ELSE v_DYNM_REPO_INTEREST_RATE END ) ELSE NULL END ) as v_FIXED_RATE,
	 v_FIXED_RATE as FIXED_RATE,
	 ( CASE WHEN ( ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'MODI' AND ACTION_TYPE != 'CORR' ) OR v_FIXED_RATE IS NULL THEN NULL ELSE :LKP.LKP_APPLICATION_VARIABLES_STR4 ( 'SFTR_TRANSACTIONS_STATIC',
	 'DAY_COUNT_CONVENTION',
	 'CALM_LTD_TRADES',
	 MONEY_BASIS ) END ) as DAY_COUNT_CONVENTION,
	 ( CASE WHEN ( ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' ) AND v_FIXED_RATE IS NOT NULL THEN 'C' ELSE NULL END ) as DAY_COUNT_CONVETION_TYPE,
	 ( CASE WHEN IN ( ACTION_TYPE,
	 'NEWT',
	 'MODI',
	 'CORR' ) = 1 AND FLOAT_RATE IS NOT NULL THEN :LKP.LKP_APPLICATION_VARIABLES_STR4 ( 'SFTR_TRANSACTIONS_STATIC',
	 'FLOATING_RATE',
	 'CALM_LTD_TRADES',
	 FLOAT_RATE ) ELSE NULL END ) as v_FLOAT_RATE,
	 v_FLOAT_RATE as O_FLOAT_RATE,
	 :LKP.LKP_APPLICATION_VARIABLES_STR4 ( 'SFTR_TRANSACTIONS_STATIC',
	 'FLOATING_RATE_PAYMT_FREQ',
	 'CALM_LTD_TRADES',
	 FLOAT_RATE_PAY_FREQ ) as v_FLT_RATE_ACTUALS_STR,
	 :LKP.LKP_APPLICATION_VARIABLES_STR4 ( 'SFTR_TRANSACTIONS_STATIC',
	 'FLOATING_RATE_PAYMT_FREQ',
	 'CALM_LTD_TRADES',
	 REGEXP_REPLACE ( FLOAT_RATE_PAY_FREQ,
	 '[^a-z A-Z]',
	 '',
	 '[^A-Za-z0-9_]',
	 '' ) ) as v_FLT_RATE_AFTR_REGRPLC_STR,
	 ( CASE WHEN v_FLT_RATE_ACTUALS_STR IS NULL THEN v_FLT_RATE_AFTR_REGRPLC_STR ELSE v_FLT_RATE_ACTUALS_STR END ) as v_FLT_RATE_FINAL_STR,
	 :LKP.LKP_APPLICATION_VARIABLES_NUM ( 'SFTR_TRANSACTIONS_STATIC',
	 'FLOATING_RATE_PAYMT_FREQ',
	 'CALM_LTD_TRADES',
	 FLOAT_RATE_PAY_FREQ ) as v_FLT_RATE_ACTUALS_NUM,
	 :LKP.LKP_APPLICATION_VARIABLES_NUM ( 'SFTR_TRANSACTIONS_STATIC',
	 'FLOATING_RATE_PAYMT_FREQ',
	 'CALM_LTD_TRADES',
	 REGEXP_REPLACE ( FLOAT_RATE_PAY_FREQ,
	 '[^a-z A-Z]',
	 '',
	 '[^A-Za-z0-9_]',
	 '' ) ) as v_FLT_RATE_AFTR_REGRPLC_NUM,
	 ( CASE WHEN v_FLT_RATE_ACTUALS_NUM IS NULL THEN v_FLT_RATE_AFTR_REGRPLC_NUM ELSE v_FLT_RATE_ACTUALS_NUM END ) as v_FLT_RATE_FINAL_NUM,
	 ( CASE WHEN IN ( ACTION_TYPE,
	 'NEWT',
	 'MODI',
	 'CORR' ) = 1 AND FLOAT_RATE IS NOT NULL THEN :LKP.LKP_APPLICATION_VARIABLES_STR5 ( 'SFTR_TRANSACTIONS_STATIC',
	 'FLOATING_RATE',
	 'CALM_LTD_TRADES',
	 FLOAT_RATE ) ELSE NULL END ) as FLOAT_RATE_TYPE,
