	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'COLU' OR ACTION_TYPE = 'CORR' OR ACTION_TYPE = 'MODI' THEN ( CASE WHEN PARENT_COUNTERPARTY IS NOT NULL AND TRD_CTRPTY_COUNTRY_CODE  !=  PARENT_COUNTRY_CODE THEN TRD_CTRPTY_COUNTRY_CODE ELSE NULL END ) ELSE null END ) as OTHER_PARTY_BRANCH,
	 ( CASE WHEN ( ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'MODI' AND ACTION_TYPE != 'CORR' ) OR ( v_FLOAT_RATE IS NULL ) THEN NULL ELSE :LKP.LKP_APPLICATION_VARIABLES_STR4 ( 'SFTR_TRANSACTIONS_STATIC',
	 'DAY_COUNT_CONVENTION',
	 'CALM_LTD_TRADES',
	 MONEY_BASIS ) END ) as FLT_DAY_COUNT_CONVENTION,
	 ( CASE WHEN ( ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' ) AND v_FLOAT_RATE IS NOT NULL THEN 'C' ELSE NULL END ) as FLT_DAY_COUNT_CONVENTION_TYPE,
	 ( CASE WHEN ( ACTION_TYPE != 'NEWT' AND ACTION_TYPE != 'COLU' AND ACTION_TYPE != 'CORR' ) OR v_COLL_COMP_TYPE = 'CASH' THEN NULL ELSE ( CASE WHEN ACTION_TYPE = 'NEWT' THEN ( CASE WHEN PRODUCT_TYPE = 'Repo' AND PRODUCT_SUBTYPE = 'Standard' THEN COLLATERAL_CURRENCY ELSE NULL END ) ELSE COLLATERAL_CURRENCY END ) END ) as COLL_MARKET_VAL_CCY,
	 ( CASE WHEN ACTION_TYPE = 'NEWT' OR ACTION_TYPE = 'MODI' OR ACTION_TYPE = 'CORR' THEN PARENT_COUNTRY_CODE ELSE NULL END ) as OTHER_PARTY_COUNTRY
From dsJoiner_EXP_FORMAT0Out as dsJoiner_EXP_FORMAT0Out
LEFT JOIN (
SELECT UPDATED_DATE, UTI FROM (   SELECT UPDATED_DATE, UTI,   ROW_NUMBER() OVER (PARTITION BY UTI ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT UPDATED_DATE, UTI,   ROW_NUMBER() OVER (PARTITION BY UTI ORDER BY UTI NULLS LAST) AS rnk_fst     FROM ( SELECT        RR_BNK_REPO_INV_FACT.UPDATED_DATE as UPDATED_DATE,        RR_BNK_REPO_INV_FACT.UTI as UTI  FROM        RR_BNK_REPO_INV_FACT  INNER JOIN      ENTITY_DIM   ON    RR_BNK_REPO_INV_FACT.ENTITY_ID= ENTITY_DIM.ID AND     ENTITY_DIM.NAME= '{{ var("ENTITY") }}'  WHERE        BUSINESS_DATE =  (SELECT        MAX(BATCH_BUSINESS_FROM_DATE)  FROM        BATCH_MASTER  WHERE       BATCH_FEED_INFO= 'BNK' AND      BATCH_STATUS= 'C' AND      BATCH_TYPE= 'EOD' AND        BATCH_BUSINESS_FROM_DATE <  (SELECT        BATCH_BUSINESS_FROM_DATE  FROM        BATCH_MASTER  WHERE       BATCH_FEED_INFO= 'SFTR_CALM_TRANSACTION_LIVE_LOAD_LTD' AND      BATCH_STATUS= 'I')) )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
