LEFT JOIN (
SELECT REPO_START_DATE, COUNTERPARTY, BUSINESS_DATE FROM (   SELECT REPO_START_DATE, COUNTERPARTY, BUSINESS_DATE,   ROW_NUMBER() OVER (PARTITION BY COUNTERPARTY, BUSINESS_DATE ORDER BY COUNTERPARTY, BUSINESS_DATE ASC NULLS LAST) AS rn   FROM ( SELECT        MAX(RR_BNK_REPO_INV_FACT.REPO_START_DATE) as REPO_START_DATE,        RR_BNK_REPO_INV_FACT.ENTITY_ID as ENTITY_ID,        RR_BNK_REPO_INV_FACT.PRODUCT_TYPE as PRODUCT_TYPE,        RR_BNK_REPO_INV_FACT.PRODUCT_SUBTYPE as PRODUCT_SUBTYPE,        RR_BNK_REPO_INV_FACT.COUNTERPARTY as COUNTERPARTY,        RR_BNK_REPO_INV_FACT.BUSINESS_DATE as BUSINESS_DATE  FROM        RR_BNK_REPO_INV_FACT  WHERE       PRODUCT_TYPE= 'REPO' AND      PRODUCT_SUBTYPE= 'STANDARD' AND      REPO_START_DATE <= TO_DATE('{{ var("BUSINESS_DATE") }}','YYYYMMDD') AND      BUSINESS_DATE= TO_DATE('{{ var("BUSINESS_DATE") }}','YYYYMMDD') AND         ENTITY_ID IN  (SELECT        ENTITY_DIM.ID  FROM        ENTITY_DIM  WHERE     ENTITY_DIM.NAME= '{{ var("ENTITY") }}')  GROUP BY        ENTITY_ID,        PRODUCT_TYPE,        PRODUCT_SUBTYPE,        COUNTERPARTY,        BUSINESS_DATE  ORDER BY        REPO_START_DATE DESC ) ) t WHERE rn = 1
) dsf_37
ON dsf_37.COUNTERPARTY = COUNTERPARTY AND dsf_37.BUSINESS_DATE = BUSINESS_DATE
