EXP_FINALOut as (
	/* transType: "Expression" */
Select 
	LPAD ( GENERATED_SEQ,
	 9,
	 '0' ) as v_SEQ_LPAD_TO_9,
	 DATEDIFF ( SECOND,
	 TO_TIMESTAMP ( '01/01/1970 00:00:00',
	 'DD-MM-YYYY HH24:MI:SS' ),
	 CURRENT_TIMESTAMP ) as v_EPOC_TIME,
	 v_EPOC_TIME || v_SEQ_LPAD_TO_9 as v_CONCATE_ID,
	 v_CONCATE_ID as ID,
	 '{{ var("BATCH_ID") }}' as BATCH_ID,
	 dsf_1.ID as BATCH_DETAILS_ID,
	 TO_DATE ( '{{ var("BUSINESS_DATE") }}',
	 'YYYYMMDD' ) as BUSINESS_DATE,
	 TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
	 'DD-MON-YYYY HH24:MI:SS' ) as BATCH_START_DATE,
	 TO_DATE ( '{{ var("BUSINESS_DATE") }}',
	 'YYYYMMDD' ) as V_BUSINESS_DATE,
	 ENTITY as ENTITY,
	 'CALM LTD' as SERVICE,
	 PRODUCT as PRODUCT,
	 SUBMITTING_ENTITY as SUBMITTING_ENTITY,
	 REPORTING_COUNTERPARTY as REPORTING_COUNTERPARTY,
	 RESPONSIBLE_ENTITY as RESPONSIBLE_ENTITY,
	 ACTION_TYPE as ACTION_TYPE,
	 ( CASE WHEN ACTION_TYPE IS NULL THEN 'N/A' ELSE ACTION_TYPE END ) as v_ACTION_TYPE,
	 NULL as NULL_VALUES,
	 REPORTING_PARTY_NATURE as REPORTING_PARTY_NATURE,
	 REPORTING_PARTY_SECTOR as REPORTING_PARTY_SECTOR,
	 COUNTERPARTY_SIDE as COUNTERPARTY_SIDE,
	 OTHER_PARTY as OTHER_PARTY,
	 COUNTERPARTY as COUNTERPARTY,
	 OTHER_PARTY_ID_TYPE as OTHER_PARTY_ID_TYPE,
	 OTHER_PARTY_COUNTRY as OTHER_PARTY_COUNTRY,
	 TRIPARTY_AGENT as TRIPARTY_AGENT,
	 CSD_OR_INDIRECT as CSD_OR_INDIRECT,
	 CSD_OR_INDIRECT_TYPE as CSD_OR_INDIRECT_TYPE,
	 UTI as UTI,
	 EVENT_DATE as EVENT_DATE,
	 TYPE_OF_SFT as TYPE_OF_SFT,
	 CLEARED as CLEARED,
	 TRADING_VENUE as TRADING_VENUE,
	 MASTER_AGREEMENT_TYPE as MASTER_AGREEMENT_TYPE,
	 MASTER_AGREEMENT_TYPE_ID as MASTER_AGREEMENT_TYPE_ID,
	 MASTER_AGREEMENT_VERSION as MASTER_AGREEMENT_VERSION,
	 EXECUTION_TIMESTAMP_UTC as EXECUTION_TIMESTAMP_UTC,
	 RTRIM ( LTRIM ( REGEXP_REPLACE ( EXECUTION_TIMESTAMP_UTC,
	 '[T Z]',
	 ' ',
	 '[^A-Za-z0-9_]',
	 '' ) ) ) as v_EXECUTION_TIMESTAMP,
