	 'EXECUTION_TIMESTAMP' as ATTRIBUTE_NAME_EXECUTION_TIMESTAMP,
	 'VALUE_DATE' as ATTRIBUTE_NAME_VALUE_DATE,
	 'MATURITY_DATE' as ATTRIBUTE_NAME_MATURITY_DATE,
	 'FIXED_RATE' as ATTRIBUTE_NAME_FIXED_RATE,
	 'PRINCIPLE_ON_MATURITY_DATE' as ATTRIBUTE_NAME_PRINCIPLE_ON_MATURITY_DATE,
	 'COLL_SEC_ID' as ATTRIBUTE_NAME_COLL_SEC_ID,
	 'COLL_SEC_ID1' as ATTRIBUTE_NAME_COLL_SEC_ID1,
	 'COLL_SEC_CLASSIF' as ATTRIBUTE_NAME_COLL_SEC_CLASSIF,
	 'COLL_QTY_OR_NOMINAL_AMT' as ATTRIBUTE_NAME_COLL_QTY_OR_NOMINAL_AMT,
	 'COLL_NOMINAL_CCY' as ATTRIBUTE_NAME_COLL_NOMINAL_CCY,
	 'COLL_PRICE_CCY' as ATTRIBUTE_NAME_COLL_PRICE_CCY,
	 'COLL_PRICE_PER_UNIT' as ATTRIBUTE_NAME_COLL_PRICE_PER_UNIT,
	 'COLL_PRICE_UNIT_SIGN' as ATTRIBUTE_NAME_COLL_PRICE_UNIT_SIGN,
	 'COLL_PRICE_TYP' as ATTRIBUTE_NAME_COLL_PRICE_TYP,
	 'COLL_MARKET_VAL' as ATTRIBUTE_NAME_COLL_MARKET_VAL,
	 'COLL_HAIRCUT_OR_MARGIN' as ATTRIBUTE_NAME_COLL_HAIRCUT_OR_MARGIN,
	 'COLL_QUALITY' as ATTRIBUTE_NAME_COLL_QUALITY,
	 'COLL_SEC_MATURITY_DATE' as ATTRIBUTE_NAME_COLL_SEC_MATURITY_DATE,
	 'COLL_ISSUER_JURISDICTION' as ATTRIBUTE_NAME_COLL_ISSUER_JURISDICTION,
	 'COLL_ISSUER_LEI' as ATTRIBUTE_NAME_COLL_ISSUER_LEI,
	 ( CASE WHEN COLL_COMP_TYPE = 'SECU' THEN 1 ELSE 0 END ) as ENABLE_IND_COLL_ISSUER_LEI,
	 ( CASE WHEN COLL_SEC_ID IS NOT NULL THEN ( CASE WHEN :LKP.LKP_RCL_BOND_STATIC_COLL_SEC_ID ( V_BUSINESS_DATE,
	 ENTITY,
	 COLL_SEC_ID ) IS NULL THEN 1 ELSE 0 END ) ELSE 0 END ) as ENABLE_IND_COLL_SEC_ID1,
	 'COLL_TYPE' as ATTRIBUTE_NAME_COLL_TYPE,
	 'COLL_REUSE_AVAILABILITY' as ATTRIBUTE_NAME_COLL_REUSE_AVAILABILITY,
	 'PORTFOLIO_CODE' as ATTRIBUTE_NAME_PORTFOLIO_CODE,
	 'TRADING_VENUE' as ATTRIBUTE_NAME_TRADING_VENUE,
	 'MASTER_AGREEMENT_TYPE' as ATTRIBUTE_NAME_MASTER_AGREEMENT_TYPE,
	 'MASTER_AGREEMENT_VERSION' as ATTRIBUTE_NAME_MASTER_AGREEMENT_VERSION,
	 'PRINCIPLE_ON_VALUE_DATE' as ATTRIBUTE_NAME_PRINCIPLE_ON_VALUE_DATE,
	 'PRINCPLE_CURR' as ATTRIBUTE_NAME_PRINCPLE_CURR,
	 'ACTION_TYPE' as ATTRIBUTE_NAME_ACTION_TYPE,
	 'TERMINATION_DATE' as ATTRIBUTE_NAME_TERMINATION_DATE,
	 'PRINCIPLE_ON_VALUE_DATE1' as ATTRIBUTE_NAME_PRINCIPLE_ON_VALUE_DATE_50,
	 'OTHER_PARTY1' as ATTRIBUTE_NAME_OTHER_PARTY_VAL51,
	 'FLOAT_RATE_REF_MULTIPLIER' as ATTRIBUTE_NAME_FLOAT_RATE_REF_MULTIPLIER,
	 'FLOAT_RATE_PAYMENT_MULTIPLIER' as ATTRIBUTE_NAME_FLOAT_RATE_PAYMENT_MULTIPLIER,
	 'FLOAT_RATE_RESET_MULTIPLIER' as ATTRIBUTE_NAME_FLOAT_RATE_RESET_MULTIPLIER,
	 'SPREA_SPREAD' as ATTRIBUTE_NAME_SPREA_SPREAD,
	 3 as NUMER_LIMIT_FLOAT_RATE_REF_MULTIPLIER,
	 3 as NUMER_LIMIT_FLOAT_RATE_PAYMENT_MULTIPLIER,
	 3 as NUMER_LIMIT_FLOAT_RATE_RESET_MULTIPLIER,
	 5 as NUMER_LIMIT_SPREA_SPREAD,
	 SFTR_COLL_ISSUER_JURISDICTION as SFTR_COLL_ISSUER_JURISDICTION,
	 SFTR_ISSUER_JURISDICTION as SFTR_ISSUER_JURISDICTION,
	 COUNTRY_OF_JURISDICTION as COUNTRY_OF_JURISDICTION,
	 STRING_VALUE3 as STRING_VALUE3,
	 TRD_CTRPTY_ESCB_FLAG as TRD_CTRPTY_ESCB_FLAG,
	 OTHER_PARTY_BRANCH as OTHER_PARTY_BRANCH,
	 PRODUCT_TYPE as PRODUCT_TYPE,
	 PRODUCT_SUBTYPE as PRODUCT_SUBTYPE,
	 '{{ var("EMIR_TR_EXTRACTION_MODE") }}' as o_EMIR_TR_EXTRACTION_MODE,
	 '{{ var("FILE_SPLT_CNT") }}' as o_FILE_SPLIT_COUNT,
	 FLT_DAY_COUNT_CONVENTION as FLT_DAY_COUNT_CONVENTION,
	 FLT_DAY_COUNT_CONVENTION_TYPE as FLT_DAY_COUNT_CONVENTION_TYPE,
	 COLL_MARKET_VAL_CCY as COLL_MARKET_VAL_CCY,
	 'ACTION_TYPE1' as ATTRIBUTE_NAME_ACTION_TYPE1,
	 ( CASE WHEN UTI IS NOT NULL THEN dsf_3.ACTION_TYPE ELSE 'N/A' END ) as v_PREV_ACTION_TYP_ARCH,
	 v_PREV_ACTION_TYP_ARCH as O_PREV_ACTION_TYP_ARCH,
	 ( CASE WHEN UTI IS NOT NULL THEN dsf_4.ACTION_TYPE ELSE 'N/A' END ) as v_ACTION_TYP_CURR_DAY,
	 IFF ( v_ACTION_TYPE = 'NEWT' AND v_PREV_ACTION_TYP_ARCH IS NULL,
	 0,
	 ( CASE WHEN IN ( v_ACTION_TYPE,
	 'EROR',
	 'CORR' ) = 1 AND v_PREV_ACTION_TYP_ARCH IS NOT NULL AND v_PREV_ACTION_TYP_ARCH  !=  'EROR' THEN 0 ELSE ( CASE WHEN IN ( v_ACTION_TYPE,
	 'ETRM',
	 'MODI' ) = 1 AND v_PREV_ACTION_TYP_ARCH IS NOT NULL AND v_PREV_ACTION_TYP_ARCH  !=  'EROR' AND v_PREV_ACTION_TYP_ARCH  !=  'ETRM' THEN 0 ELSE ( CASE WHEN v_ACTION_TYPE = 'COLU' AND ( ( v_PREV_ACTION_TYP_ARCH IS NOT NULL AND IN ( v_PREV_ACTION_TYP_ARCH,
	 'NEWT',
	 'COLU',
	 'MODI',
	 'CORR' ) = 1 ) OR IN ( v_ACTION_TYP_CURR_DAY,
	 'CORR',
	 'MODI',
	 'NEWT' ) = 1 ) THEN 0 ELSE 1 END ) END ) END ) ) as ENABLE_IND_COLL_ACTION_TYPE1,
	 'VALUE_DT_OF_COLL' as ATTRIBUTE_NAME_VAL_DT_OF_COLL,
	 ( CASE WHEN IN ( v_ACTION_TYPE,
	 'COLU',
	 'CORR' ) = 1 AND UPPER ( COLL_OF_NET_EXPOSURE ) = 'TRUE' THEN ( CASE WHEN VALUE_DT_OF_COLL IS NULL THEN 1 ELSE 0 END ) ELSE 0 END ) as ENABLE_IND_COLL_VAL_DT_OF_COLL,
	 '{{ var("ENTITY_SUFFIX") }}' as ENTITY_SUFFIX
From DSR_EXP_FINALOut as DSR_EXP_FINALOut
LEFT JOIN (
SELECT ID, BATCH_ID, TARGET_TABLE_NAME, FILE_NAME FROM (   SELECT ID, BATCH_ID, TARGET_TABLE_NAME, FILE_NAME,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, TARGET_TABLE_NAME, FILE_NAME ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT ID, BATCH_ID, TARGET_TABLE_NAME, FILE_NAME,   ROW_NUMBER() OVER (PARTITION BY BATCH_ID, TARGET_TABLE_NAME, FILE_NAME ORDER BY BATCH_ID, TARGET_TABLE_NAME, FILE_NAME NULLS LAST) AS rnk_fst     FROM ( SELECT        BATCH_DETAILS.ID as ID,        BATCH_DETAILS.BATCH_ID as BATCH_ID,        BATCH_DETAILS.TARGET_TABLE_NAME as TARGET_TABLE_NAME,        BATCH_DETAILS.FILE_NAME as FILE_NAME,        BATCH_DETAILS.STATUS as STATUS  FROM  (SELECT        id,        TARGET_TABLE_NAME,        BATCH_ID,        STATUS,        ACTIVE_FLAG,        BATCH_DETAILS_START_TIME,        FILE_NAME,        RANK() OVER(partition by batch_id,TARGET_TABLE_NAME,FILE_NAME order by BATCH_DETAILS_START_TIME DESC) as RANK  FROM        BATCH_DETAILS) BATCH_DETAILS  WHERE       RANK= 1 AND      STATUS= 'I' AND      ACTIVE_FLAG= 1 )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.BATCH_ID = '{{ var("BATCH_ID") }}' AND dsf_1.TARGET_TABLE_NAME = '{{ var("TARGET_NAME") }}' AND dsf_1.FILE_NAME = '{{ var("SOURCE_NAME") }}'
LEFT JOIN (
SELECT ISIN, BUSINESS_DATE, ENTITY, ISIN FROM (   SELECT ISIN, BUSINESS_DATE, ENTITY, ISIN,   ROW_NUMBER() OVER (PARTITION BY BUSINESS_DATE, ENTITY, ISIN ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT ISIN, BUSINESS_DATE, ENTITY, ISIN,   ROW_NUMBER() OVER (PARTITION BY BUSINESS_DATE, ENTITY, ISIN ORDER BY BUSINESS_DATE, ENTITY, ISIN NULLS LAST) AS rnk_fst     FROM ( SELECT        RCL_BOND_STATIC.BUSINESS_DATE as BUSINESS_DATE,        RCL_BOND_STATIC.ENTITY as ENTITY,        RCL_BOND_STATIC.ISIN as ISIN  FROM        RCL_BOND_STATIC  WHERE     RCL_BOND_STATIC.BUSINESS_DATE= TO_DATE('{{ var("BUSINESS_DATE") }}','YYYYMMDD') - - )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.BUSINESS_DATE = V_BUSINESS_DATE AND dsf_2.ENTITY = ENTITY AND dsf_2.ISIN = COLL_SEC_ID
LEFT JOIN (
SELECT ACTION_TYPE, UTI FROM (   SELECT ACTION_TYPE, UTI,   ROW_NUMBER() OVER (PARTITION BY UTI ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT ACTION_TYPE, UTI,   ROW_NUMBER() OVER (PARTITION BY UTI ORDER BY UTI NULLS LAST) AS rnk_fst     FROM ( SELECT        SFTR_TRANSACTIONS_LIVE_ARCH.ACTION_TYPE as ACTION_TYPE,        SFTR_TRANSACTIONS_LIVE_ARCH.UTI as UTI  FROM        SFTR_TRANSACTIONS_LIVE_ARCH  WHERE       SFTR_TRANSACTIONS_LIVE_ARCH.MD_ERROR_IND= 0 AND      SFTR_TRANSACTIONS_LIVE_ARCH.SERVICE= 'CALM LTD' AND      BUSINESS_DATE <= TO_DATE('{{ var("BUSINESS_DATE") }}','YYYYMMDD')  ORDER BY        SFTR_TRANSACTIONS_LIVE_ARCH.BUSINESS_DATE,        CREATED_TS - - )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.UTI = UTI
LEFT JOIN (
SELECT ACTION_TYPE, UTI FROM (   SELECT ACTION_TYPE, UTI,   ROW_NUMBER() OVER (PARTITION BY UTI ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst   FROM (     SELECT ACTION_TYPE, UTI,   ROW_NUMBER() OVER (PARTITION BY UTI ORDER BY UTI NULLS LAST) AS rnk_fst     FROM ( SELECT        SFTR_TRANSACTIONS_LIVE.ACTION_TYPE as ACTION_TYPE,        SFTR_TRANSACTIONS_LIVE.UTI as UTI  FROM        SFTR_TRANSACTIONS_LIVE  WHERE       BUSINESS_DATE= TO_DATE('{{ var("BUSINESS_DATE") }}','YYYYMMDD') AND      SFTR_TRANSACTIONS_LIVE.SERVICE= 'CALM LTD' AND      SFTR_TRANSACTIONS_LIVE.MD_ERROR_IND= 0 AND     ACTION_TYPE IN('CORR','MODI','NEWT') - - )   ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_4
ON dsf_4.UTI = UTI
),

EXP_FINALOut2 as (
	/* transType: "Expression" */
Select 
	LPAD ( GENERATED_SEQ,
	 9,
	 '0' ) as v_SEQ_LPAD_TO_9,
	 DATEDIFF ( SECOND,
	 TO_TIMESTAMP ( '01/01/1970 00:00:00',
	 'DD-MM-YYYY HH24:MI:SS' ),
	 CURRENT_TIMESTAMP ) as v_EPOC_TIME,
	 v_EPOC_TIME || v_SEQ_LPAD_TO_9 as v_CONCATE_ID,
	 v_CONCATE_ID as ID,
	 '{{ var("BATCH_ID") }}' as BATCH_ID,
