) dsf_1
ON dsf_1.VARIABLE_NAME = in_ATTRIBUTE_NAME AND dsf_1.STRING_VALUE2 = in_VALIDATION_NAME
LEFT JOIN (
SELECT NUMBER_VALUE, VARIABLE_NAME, STRING_VALUE2 FROM (  SELECT NUMBER_VALUE, VARIABLE_NAME, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE2 ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT NUMBER_VALUE, VARIABLE_NAME, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE2 ORDER BY VARIABLE_NAME, STRING_VALUE2 NULLS LAST) AS rnk_fst   FROM ( SELECT    NUMBER_VALUE as NUMBER_VALUE,    VARIABLE_NAME as VARIABLE_NAME,    STRING_VALUE2 as STRING_VALUE2 FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
