	 ( CASE WHEN v_VAL_CHECK = 'F' THEN in_ATTRIBUTE_NAME || ':' || in_ATTRIBUTE_VALUE ELSE NULL END ) as v_ERROR_MESSAGE,
	 v_ERROR_MESSAGE as o_ERROR_MESSAGE,
	 ( CASE WHEN v_VAL_CHECK = 'F' THEN v_VALIDATION_SEVERITY ELSE 0 END ) as o_ERROR_SEVERITY,
	 v_VALIDATION_ERROR_CODE as o_VALIDATION_ERROR_CODE
From DSR_EXP_SFTR_VALIDATION_NUMBER_LIMIT_CHECK_SPREADOut as DSR_EXP_SFTR_VALIDATION_NUMBER_LIMIT_CHECK_SPREADOut
LEFT JOIN (
SELECT ACTIVE_Y_N, VARIABLE_NAME, STRING_VALUE2 FROM (  SELECT ACTIVE_Y_N, VARIABLE_NAME, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE2 ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT ACTIVE_Y_N, VARIABLE_NAME, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE2 ORDER BY VARIABLE_NAME, STRING_VALUE2 NULLS LAST) AS rnk_fst   FROM ( SELECT    ACTIVE_Y_N as ACTIVE_Y_N,    VARIABLE_NAME as VARIABLE_NAME,    STRING_VALUE2 as STRING_VALUE2 FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_1
ON dsf_1.VARIABLE_NAME = in_ATTRIBUTE_NAME AND dsf_1.STRING_VALUE2 = in_VALIDATION_NAME
LEFT JOIN (
SELECT NUMBER_VALUE, VARIABLE_NAME, STRING_VALUE2 FROM (  SELECT NUMBER_VALUE, VARIABLE_NAME, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE2 ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT NUMBER_VALUE, VARIABLE_NAME, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE2 ORDER BY VARIABLE_NAME, STRING_VALUE2 NULLS LAST) AS rnk_fst   FROM ( SELECT    NUMBER_VALUE as NUMBER_VALUE,    VARIABLE_NAME as VARIABLE_NAME,    STRING_VALUE2 as STRING_VALUE2 FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_2
ON dsf_2.VARIABLE_NAME = in_ATTRIBUTE_NAME AND dsf_2.STRING_VALUE2 = in_VALIDATION_NAME
LEFT JOIN (
SELECT STRING_VALUE, VARIABLE_NAME, STRING_VALUE2 FROM (  SELECT STRING_VALUE, VARIABLE_NAME, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE2 ORDER BY rnk_fst DESC NULLS LAST) AS rnk_lst  FROM (   SELECT STRING_VALUE, VARIABLE_NAME, STRING_VALUE2,  ROW_NUMBER() OVER (PARTITION BY VARIABLE_NAME, STRING_VALUE2 ORDER BY VARIABLE_NAME, STRING_VALUE2 NULLS LAST) AS rnk_fst   FROM ( SELECT    STRING_VALUE as STRING_VALUE,    VARIABLE_NAME as VARIABLE_NAME,    STRING_VALUE2 as STRING_VALUE2 FROM    APPLICATION_VARIABLES )  ) lkp_inner ) lkp_outer WHERE rnk_lst = 1
) dsf_3
ON dsf_3.VARIABLE_NAME = in_ATTRIBUTE_NAME AND dsf_3.STRING_VALUE2 = in_VALIDATION_NAME
),

EXP_VAL_CHECK_1Out as (
	/* transType: "Expression" */
Select 
	TRANSACTION_DATE_TIME as TRANSACTION_DATE_TIME,
	 ACTION_TYPE as ACTION_TYPE,
	 COLL_OF_NET_EXPOSURE as COLL_OF_NET_EXPOSURE,
	 ( CASE WHEN COLL_OF_NET_EXPOSURE IS NULL THEN 'N/A' ELSE COLL_OF_NET_EXPOSURE END ) as v_COLL_OF_NET_EXPOSURE,
	 MATURITY_DATE as MATURITY_DATE,
	 ( CASE WHEN MATURITY_DATE IS NULL THEN TO_DATE ( '9999-12-31',
	 'YYYY-MM-DD' ) ELSE TO_DATE ( TO_VARCHAR ( MATURITY_DATE,
	 'YYYYMMDD' ),
	 'YYYYMMDD' ) END ) as v_MATURITY_DATE,
	 TO_DATE ( TO_VARCHAR ( CURRENT_TIMESTAMP,
	 'YYYYMMDD' ),
	 'YYYYMMDD' ) as v_SYSDATE,
	 EXECUTION_TIMESTAMP as EXECUTION_TIMESTAMP,
	 RTRIM ( LTRIM ( REGEXP_REPLACE ( EXECUTION_TIMESTAMP,
	 '[T Z]',
	 ' ',
	 '[^A-Za-z0-9_]',
	 '' ) ) ) as v_EXECUTION_TIMESTAMP,
	 ( CASE WHEN v_EXECUTION_TIMESTAMP IS NULL THEN NULL ELSE TO_DATE ( TO_VARCHAR ( TO_TIMESTAMP ( v_EXECUTION_TIMESTAMP,
	 'YYYY-MM-DD HH24:MI:SS' ),
	 'YYYY-MM-DD' ),
	 'YYYY-MM-DD' ) END ) as v_EXECUTION_TIMESTAMP_date,
	 FIXED_RATE as FIXED_RATE,
	 FLOAT_RATE as FLOAT_RATE,
	 OPEN_TERM as OPEN_TERM,
	 COLL_COMP_TYPE as COLL_COMP_TYPE,
	 COLL_BASKET_ID as COLL_BASKET_ID,
	 dsf_1.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COUNTERPARTY_SIDE,
	 dsf_2.NUMBER_VALUE as v_VALIDATION_SEVERITY_COUNTERPARTY_SIDE,
	 dsf_3.STRING_VALUE as v_VALIDATION_ERROR_CODE_COUNTERPARTY_SIDE,
	 ( CASE WHEN in_ENABLE_IND_COUNTERPARTY_SIDE = 1 AND v_VALIDATION_ACTIVE_COUNTERPARTY_SIDE = 'Y' THEN ( CASE WHEN IN ( ACTION_TYPE,
	 'NEWT',
	 'MODI',
	 'CORR' ) THEN ( CASE WHEN IN ( in_ATTRIBUTE_VALUE_COUNTERPARTY_SIDE,
	 'GIVE',
	 'TAKE' ) = 1 THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COUNTERPARTY_SIDE,
	 v_VAL_CHECK_COUNTERPARTY_SIDE as o_VALIDATION_PASS_FAIL_COUNTERPARTY_SIDE,
	 ( CASE WHEN v_VAL_CHECK_COUNTERPARTY_SIDE = 'F' THEN in_ATTRIBUTE_NAME_COUNTERPARTY_SIDE || ':' || in_ATTRIBUTE_VALUE_COUNTERPARTY_SIDE ELSE NULL END ) as v_ERROR_MESSAGE_COUNTERPARTY_SIDE,
	 v_ERROR_MESSAGE_COUNTERPARTY_SIDE as o_ERROR_MESSAGE_COUNTERPARTY_SIDE,
	 ( CASE WHEN v_VAL_CHECK_COUNTERPARTY_SIDE = 'F' THEN v_VALIDATION_SEVERITY_COUNTERPARTY_SIDE ELSE 0 END ) as o_ERROR_SEVERITY_COUNTERPARTY_SIDE,
	 v_VALIDATION_ERROR_CODE_COUNTERPARTY_SIDE as o_VALIDATION_ERROR_CODE_COUNTERPARTY_SIDE,
	 dsf_4.ACTIVE_Y_N as v_VALIDATION_ACTIVE_OTHER_PARTY_COUNTRY,
	 ( CASE WHEN v_VALIDATION_ACTIVE_OTHER_PARTY_COUNTRY IS NULL THEN 'N' ELSE v_VALIDATION_ACTIVE_OTHER_PARTY_COUNTRY END ) as v_VALIDATION_ACTIVE_NVL_OTHER_PARTY_COUNTRY,
	 dsf_5.NUMBER_VALUE as v_VALIDATION_SEVERITY_OTHER_PARTY_COUNTRY,
	 dsf_6.STRING_VALUE as v_VALIDATION_ERROR_CODE_OTHER_PARTY_COUNTRY,
	 ( CASE WHEN in_ENABLE_IND_OTHER_PARTY_COUNTRY = 1 AND v_VALIDATION_ACTIVE_NVL_OTHER_PARTY_COUNTRY = 'Y' THEN ( CASE WHEN IN ( ACTION_TYPE,
	 'NEWT',
	 'MODI',
	 'CORR' ) THEN ( CASE WHEN LENGTH ( in_ATTRIBUTE_VALUE_OTHER_PARTY_COUNTRY ) = 2 AND REGEXP_INSTR ( in_ATTRIBUTE_VALUE_OTHER_PARTY_COUNTRY,
	 '[a-zA-Z]+' ) = 1 THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_OTHER_PARTY_COUNTRY,
	 v_VAL_CHECK_OTHER_PARTY_COUNTRY as o_VALIDATION_PASS_FAIL_OTHER_PARTY_COUNTRY,
	 ( CASE WHEN v_VAL_CHECK_OTHER_PARTY_COUNTRY = 'F' THEN in_ATTRIBUTE_NAME_OTHER_PARTY_COUNTRY || ':' || in_ATTRIBUTE_VALUE_OTHER_PARTY_COUNTRY ELSE NULL END ) as v_ERROR_MESSAGE_OTHER_PARTY_COUNTRY,
	 v_ERROR_MESSAGE_OTHER_PARTY_COUNTRY as o_ERROR_MESSAGE_OTHER_PARTY_COUNTRY,
	 ( CASE WHEN v_VAL_CHECK_OTHER_PARTY_COUNTRY = 'F' THEN v_VALIDATION_SEVERITY_OTHER_PARTY_COUNTRY ELSE 0 END ) as o_ERROR_SEVERITY_OTHER_PARTY_COUNTRY,
	 v_VALIDATION_ERROR_CODE_OTHER_PARTY_COUNTRY as o_VALIDATION_ERROR_CODE_OTHER_PARTY_COUNTRY,
	 dsf_7.ACTIVE_Y_N as v_VALIDATION_ACTIVE_ACTION_TYPE,
	 ( CASE WHEN v_VALIDATION_ACTIVE_ACTION_TYPE IS NULL THEN 'N' ELSE v_VALIDATION_ACTIVE_ACTION_TYPE END ) as v_VALIDATION_ACTIVE_NVL_ACTION_TYPE,
	 dsf_8.NUMBER_VALUE as v_VALIDATION_SEVERITY_ACTION_TYPE,
	 dsf_9.STRING_VALUE as v_VALIDATION_ERROR_CODE_ACTION_TYPE,
	 ( CASE WHEN in_ENABLE_IND_ACTION_TYPE = 1 AND v_VALIDATION_ACTIVE_NVL_ACTION_TYPE = 'Y' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_ACTION_TYPE IS NOT NULL THEN 'P' ELSE 'F' END ) ELSE 'P' END ) as v_VAL_CHECK_ACTION_TYPE,
	 v_VAL_CHECK_ACTION_TYPE as o_VALIDATION_PASS_FAIL_ACTION_TYPE,
	 ( CASE WHEN v_VAL_CHECK_ACTION_TYPE = 'F' THEN in_ATTRIBUTE_NAME_ACTION_TYPE || ':' || in_ATTRIBUTE_VALUE_ACTION_TYPE ELSE NULL END ) as v_ERROR_MESSAGE_ACTION_TYPE,
	 v_ERROR_MESSAGE_ACTION_TYPE as o_ERROR_MESSAGE_ACTION_TYPE,
	 ( CASE WHEN v_VAL_CHECK_ACTION_TYPE = 'F' THEN v_VALIDATION_SEVERITY_ACTION_TYPE ELSE 0 END ) as o_ERROR_SEVERITY_ACTION_TYPE,
	 v_VALIDATION_ERROR_CODE_ACTION_TYPE as o_VALIDATION_ERROR_CODE_ACTION_TYPE,
	 dsf_10.ACTIVE_Y_N as v_VALIDATION_ACTIVE_UTI,
	 dsf_11.NUMBER_VALUE as v_VALIDATION_SEVERITY_UTI,
	 dsf_12.STRING_VALUE as v_VALIDATION_ERROR_CODE_UTI,
	 REGEXP_REPLACE ( in_ATTRIBUTE_VALUE_UTI,
	 '[0-9A-Z]',
	 '',
	 '[^A-Za-z0-9_]',
	 '' ) as v_UTI_REPLACE_ALPHANUMERIC,
	 v_UTI_REPLACE_ALPHANUMERIC as v_UTI_POST_REPLACE,
	 ( CASE WHEN in_ENABLE_IND_UTI = 1 AND v_VALIDATION_ACTIVE_UTI = 'Y' THEN ( CASE WHEN v_COLL_OF_NET_EXPOSURE  !=  'TRUE' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_UTI IS NOT NULL AND ( LENGTH ( in_ATTRIBUTE_VALUE_UTI ) <= 52 ) AND ( v_UTI_POST_REPLACE IS NULL OR LENGTH ( v_UTI_POST_REPLACE ) = 0 ) THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_UTI,
	 v_VAL_CHECK_UTI as o_VALIDATION_PASS_FAIL_UTI,
	 IFF ( v_VAL_CHECK_UTI = 'F',
	 in_ATTRIBUTE_NAME_UTI || ':' || REPLACE ( REPLACE ( in_ATTRIBUTE_VALUE_UTI,
	 '|',
	 '*PIPE*' ),
	 '~',
	 '*TILD*' ),
	 NULL ) as v_ERROR_MESSAGE_UTI,
	 v_ERROR_MESSAGE_UTI as o_ERROR_MESSAGE_UTI,
	 ( CASE WHEN v_VAL_CHECK_UTI = 'F' THEN v_VALIDATION_SEVERITY_UTI ELSE 0 END ) as o_ERROR_SEVERITY_UTI,
	 v_VALIDATION_ERROR_CODE_UTI as o_VALIDATION_ERROR_CODE_UTI,
	 dsf_13.ACTIVE_Y_N as v_VALIDATION_ACTIVE_EVENT_DATE,
	 dsf_14.NUMBER_VALUE as v_VALIDATION_SEVERITY_EVENT_DATE,
	 ( CASE WHEN in_ENABLE_IND_EVENT_DATE = 1 AND v_VALIDATION_ACTIVE_EVENT_DATE = 'Y' THEN ( CASE WHEN ACTION_TYPE != 'EROR' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_EVENT_DATE IS NOT NULL THEN ( CASE WHEN in_ATTRIBUTE_VALUE_EVENT_DATE <= v_SYSDATE THEN ( CASE WHEN in_ATTRIBUTE_VALUE_EVENT_DATE <= v_MATURITY_DATE THEN ( CASE WHEN v_EXECUTION_TIMESTAMP_date IS NULL OR in_ATTRIBUTE_VALUE_EVENT_DATE >= v_EXECUTION_TIMESTAMP_date THEN 'P' ELSE 'F' END ) ELSE 'F' END ) ELSE 'F' END ) ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_EVENT_DATE,
	 v_VAL_CHECK_EVENT_DATE as o_VAL_PASS_FAIL_EVENT_DATE,
	 ( CASE WHEN v_VAL_CHECK_EVENT_DATE = 'F' THEN in_ATTRIBUTE_NAME_EVENT_DATE || ':' || in_ATTRIBUTE_VALUE_EVENT_DATE ELSE NULL END ) as o_ERROR_MESSAGE_EVENT_DATE,
	 ( CASE WHEN v_VAL_CHECK_EVENT_DATE = 'F' THEN v_VALIDATION_SEVERITY_EVENT_DATE ELSE 0 END ) as o_ERROR_SEVERITY_EVENT_DATE,
	 dsf_15.STRING_VALUE as o_VALIDATION_ERROR_CODE_EVENT_DATE,
	 dsf_16.ACTIVE_Y_N as v_VALIDATION_ACTIVE_TYPE_OF_SFT,
	 dsf_17.NUMBER_VALUE as v_VALIDATION_SEVERITY_TYPE_OF_SFT,
	 ( CASE WHEN in_ENABLE_IND_TYPE_OF_SFT = 1 AND v_VALIDATION_ACTIVE_TYPE_OF_SFT = 'Y' THEN ( CASE WHEN IN ( ACTION_TYPE,
	 'NEWT',
	 'MODI',
	 'COLU',
	 'CORR' ) THEN ( CASE WHEN in_ATTRIBUTE_VALUE_TYPE_OF_SFT IS NOT NULL AND IN ( in_ATTRIBUTE_VALUE_TYPE_OF_SFT,
	 'SLEB',
	 'SBSC',
	 'REPO',
	 'MGLD' ) = 1 THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_TYPE_OF_SFT,
	 v_VAL_CHECK_TYPE_OF_SFT as o_VAL_PASS_FAIL_TYPE_OF_SFT,
	 ( CASE WHEN v_VAL_CHECK_TYPE_OF_SFT = 'F' THEN in_ATTRIBUTE_NAME_TYPE_OF_SFT || ':' || in_ATTRIBUTE_VALUE_TYPE_OF_SFT ELSE NULL END ) as o_ERROR_MESSAGE_TYPE_OF_SFT,
	 ( CASE WHEN v_VAL_CHECK_TYPE_OF_SFT = 'F' THEN v_VALIDATION_SEVERITY_TYPE_OF_SFT ELSE 0 END ) as o_ERROR_SEVERITY_TYPE_OF_SFT,
	 dsf_18.STRING_VALUE as o_VALIDATION_ERROR_CODE_TYPE_OF_SFT,
	 dsf_19.ACTIVE_Y_N as v_VALIDATION_ACTIVE_EXECUTION_TIMESTAMP,
	 dsf_20.NUMBER_VALUE as v_VALIDATION_SEVERITY_EXECUTION_TIMESTAMP,
	 ( CASE WHEN in_ENABLE_IND_EXECUTION_TIMESTAMP = 1 AND v_VALIDATION_ACTIVE_EXECUTION_TIMESTAMP = 'Y' THEN ( CASE WHEN IN ( ACTION_TYPE,
	 'NEWT',
	 'MODI',
	 'CORR' ) THEN ( CASE WHEN in_ATTRIBUTE_VALUE_EXECUTION_TIMESTAMP IS NOT NULL THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_EXECUTION_TIMESTAMP,
	 v_VAL_CHECK_EXECUTION_TIMESTAMP as o_VAL_PASS_FAIL_EXECUTION_TIMESTAMP,
	 ( CASE WHEN v_VAL_CHECK_EXECUTION_TIMESTAMP = 'F' THEN in_ATTRIBUTE_NAME_EXECUTION_TIMESTAMP || ':' || in_ATTRIBUTE_VALUE_EXECUTION_TIMESTAMP ELSE NULL END ) as o_ERROR_MESSAGE_EXECUTION_TIMESTAMP,
	 ( CASE WHEN v_VAL_CHECK_EXECUTION_TIMESTAMP = 'F' THEN v_VALIDATION_SEVERITY_EXECUTION_TIMESTAMP ELSE 0 END ) as o_ERROR_SEVERITY_EXECUTION_TIMESTAMP,
	 dsf_21.STRING_VALUE as o_VALIDATION_ERROR_CODE_EXECUTION_TIMESTAMP,
	 dsf_22.ACTIVE_Y_N as v_VALIDATION_ACTIVE_VALUE_DATE,
	 dsf_23.NUMBER_VALUE as v_VALIDATION_SEVERITY_VALUE_DATE,
	 ( CASE WHEN in_ENABLE_IND_VALUE_DATE = 1 AND v_VALIDATION_ACTIVE_VALUE_DATE = 'Y' THEN ( CASE WHEN IN ( ACTION_TYPE,
	 'NEWT',
	 'MODI',
	 'CORR' ) THEN ( CASE WHEN in_ATTRIBUTE_VALUE_VALUE_DATE IS NOT NULL THEN ( CASE WHEN TO_DATE ( TO_VARCHAR ( in_ATTRIBUTE_VALUE_VALUE_DATE,
	 'YYYYMMDD' ),
	 'YYYYMMDD' ) >= v_EXECUTION_TIMESTAMP_date THEN 'P' ELSE 'F' END ) ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_VALUE_DATE,
	 v_VAL_CHECK_VALUE_DATE as o_VAL_PASS_FAIL_VALUE_DATE,
	 ( CASE WHEN v_VAL_CHECK_VALUE_DATE = 'F' THEN in_ATTRIBUTE_NAME_VALUE_DATE || ':' || in_ATTRIBUTE_VALUE_VALUE_DATE ELSE NULL END ) as o_ERROR_MESSAGE_VALUE_DATE,
	 ( CASE WHEN v_VAL_CHECK_VALUE_DATE = 'F' THEN v_VALIDATION_SEVERITY_VALUE_DATE ELSE 0 END ) as o_ERROR_SEVERITY_VALUE_DATE,
	 dsf_24.STRING_VALUE as o_VALIDATION_ERROR_CODE_VALUE_DATE,
	 dsf_25.ACTIVE_Y_N as v_VALIDATION_ACTIVE_FIXED_RATE,
	 dsf_26.NUMBER_VALUE as v_VALIDATION_SEVERITY_FIXED_RATE,
	 ( CASE WHEN SIGN ( in_ATTRIBUTE_VALUE_FIXED_RATE ) > 0 THEN ( CASE WHEN in_ATTRIBUTE_VALUE_FIXED_RATE > 99999999999 THEN 'F' ELSE 'P' END ) ELSE ( CASE WHEN in_ATTRIBUTE_VALUE_FIXED_RATE < -99999999999 THEN 'F' ELSE 'P' END ) END ) as v_DECIMAL_CHECK_FIXED_RATE,
	 ( CASE WHEN in_ENABLE_IND_FIXED_RATE = 1 AND v_VALIDATION_ACTIVE_FIXED_RATE = 'Y' AND IN ( ACTION_TYPE,
	 'NEWT',
	 'MODI',
	 'CORR' ) THEN ( CASE WHEN in_ATTRIBUTE_VALUE_TYPE_OF_SFT = 'REPO' OR in_ATTRIBUTE_VALUE_TYPE_OF_SFT = 'MGLD' THEN ( CASE WHEN ( FIXED_RATE IS NOT NULL AND v_DECIMAL_CHECK_FIXED_RATE = 'P' ) OR FLOAT_RATE IS NOT NULL THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_FIXED_RATE,
	 v_VAL_CHECK_FIXED_RATE as o_VAL_PASS_FAIL_FIXED_RATE,
	 ( CASE WHEN v_VAL_CHECK_FIXED_RATE = 'F' THEN in_ATTRIBUTE_NAME_FIXED_RATE || ':' || in_ATTRIBUTE_VALUE_FIXED_RATE ELSE NULL END ) as o_ERROR_MESSAGE_FIXED_RATE,
	 ( CASE WHEN v_VAL_CHECK_FIXED_RATE = 'F' THEN v_VALIDATION_SEVERITY_FIXED_RATE ELSE 0 END ) as o_ERROR_SEVERITY_FIXED_RATE,
	 dsf_27.STRING_VALUE as o_VALIDATION_ERROR_CODE_FIXED_RATE,
	 dsf_28.ACTIVE_Y_N as v_VALIDATION_ACTIVE_PRNCPLE_ON_MAT_DT,
	 dsf_29.NUMBER_VALUE as v_VALIDATION_SEVERITY_PRNCPLE_ON_MAT_DT,
	 ( CASE WHEN SIGN ( in_ATTRIBUTE_VALUE_PRNCPLE_ON_MAT_DT ) > 0 THEN ( CASE WHEN in_ATTRIBUTE_VALUE_PRNCPLE_ON_MAT_DT > 999999999999999999 THEN 'F' ELSE 'P' END ) ELSE ( CASE WHEN in_ATTRIBUTE_VALUE_PRNCPLE_ON_MAT_DT < -999999999999999999 THEN 'F' ELSE 'P' END ) END ) as v_DECIMAL_CHECK_PRINCIPLE_ON_MAT_DT,
	 ( CASE WHEN in_ENABLE_IND_PRNCPLE_ON_MAT_DT = 1 AND v_VALIDATION_ACTIVE_PRNCPLE_ON_MAT_DT = 'Y' THEN ( CASE WHEN OPEN_TERM = 'false' AND in_ATTRIBUTE_VALUE_FIXED_RATE IS NOT NULL THEN ( CASE WHEN in_ATTRIBUTE_VALUE_PRNCPLE_ON_MAT_DT IS NOT NULL AND v_DECIMAL_CHECK_PRINCIPLE_ON_MAT_DT = 'P' THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_PRNCPLE_ON_MAT_DT,
	 v_VAL_CHECK_PRNCPLE_ON_MAT_DT as o_VAL_PASS_FAIL_PRNCPLE_ON_MAT_DT,
	 ( CASE WHEN v_VAL_CHECK_PRNCPLE_ON_MAT_DT = 'F' THEN in_ATTRIBUTE_NAME_PRNCPLE_ON_MAT_DT || ':' || in_ATTRIBUTE_VALUE_PRNCPLE_ON_MAT_DT ELSE NULL END ) as o_ERROR_MESSAGE_PRNCPLE_ON_MAT_DT,
	 ( CASE WHEN v_VAL_CHECK_PRNCPLE_ON_MAT_DT = 'F' THEN v_VALIDATION_SEVERITY_PRNCPLE_ON_MAT_DT ELSE 0 END ) as o_ERROR_SEVERITY_PRNCPLE_ON_MAT_DT,
	 dsf_30.STRING_VALUE as o_VALIDATION_ERROR_CODE_PRNCPLE_ON_MAT_DT,
	 dsf_31.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COLL_SEC_ID,
	 dsf_32.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLL_SEC_ID,
	 ( CASE WHEN in_ENABLE_IND_COLL_SEC_ID = 1 AND v_VALIDATION_ACTIVE_COLL_SEC_ID = 'Y' THEN ( CASE WHEN COLL_COMP_TYPE = 'SECU' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_SEC_ID IS NULL THEN 'F' ELSE 'P' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COLL_SEC_ID,
	 v_VAL_CHECK_COLL_SEC_ID as o_VAL_PASS_FAIL_COLL_SEC_ID,
	 ( CASE WHEN v_VAL_CHECK_COLL_SEC_ID = 'F' THEN in_ATTRIBUTE_NAME_COLL_SEC_ID || ':' || in_ATTRIBUTE_VALUE_COLL_SEC_ID ELSE NULL END ) as o_ERROR_MESSAGE_COLL_SEC_ID,
	 ( CASE WHEN v_VAL_CHECK_COLL_SEC_ID = 'F' THEN v_VALIDATION_SEVERITY_COLL_SEC_ID ELSE 0 END ) as o_ERROR_SEVERITY_COLL_SEC_ID,
	 dsf_33.STRING_VALUE as o_VALIDATION_ERROR_CODE_COLL_SEC_ID,
	 dsf_34.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COLL_SEC_CLASSIF,
	 dsf_35.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLL_SEC_CLASSIF,
	 ( CASE WHEN in_ENABLE_IND_COLL_SEC_CLASSIF = 1 AND v_VALIDATION_ACTIVE_COLL_SEC_CLASSIF = 'Y' THEN ( CASE WHEN COLL_COMP_TYPE = 'SECU' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_SEC_CLASSIF IS NULL THEN 'F' ELSE 'P' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COLL_SEC_CLASSIF,
	 v_VAL_CHECK_COLL_SEC_CLASSIF as o_VAL_PASS_FAIL_COLL_SEC_CLASSIF,
	 ( CASE WHEN v_VAL_CHECK_COLL_SEC_CLASSIF = 'F' THEN in_ATTRIBUTE_NAME_COLL_SEC_CLASSIF || ':' || in_ATTRIBUTE_VALUE_COLL_SEC_CLASSIF ELSE NULL END ) as o_ERROR_MESSAGE_COLL_SEC_CLASSIF,
	 ( CASE WHEN v_VAL_CHECK_COLL_SEC_CLASSIF = 'F' THEN v_VALIDATION_SEVERITY_COLL_SEC_CLASSIF ELSE 0 END ) as o_ERROR_SEVERITY_COLL_SEC_CLASSIF,
	 dsf_36.STRING_VALUE as o_VALIDATION_ERROR_CODE_COLL_SEC_CLASSIF,
	 dsf_37.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COLLQTY_NOM_AMT,
	 dsf_38.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLLQTY_NOM_AMT,
	 ( CASE WHEN SIGN ( in_ATTRIBUTE_VALUE_COLLQTY_NOM_AMT ) > 0 THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLLQTY_NOM_AMT > 999999999999999999 THEN 'F' ELSE 'P' END ) ELSE ( CASE WHEN in_ATTRIBUTE_VALUE_COLLQTY_NOM_AMT < -999999999999999999 THEN 'F' ELSE 'P' END ) END ) as v_DECIMAL_CHECK_COLLQTY_NOM_AMT,
	 ( CASE WHEN in_ENABLE_IND_COLLQTY_NOM_AMT = 1 AND v_VALIDATION_ACTIVE_COLLQTY_NOM_AMT = 'Y' THEN ( CASE WHEN COLL_COMP_TYPE = 'SECU' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLLQTY_NOM_AMT IS NOT NULL AND v_DECIMAL_CHECK_COLLQTY_NOM_AMT = 'P' THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COLLQTY_NOM_AMT,
	 v_VAL_CHECK_COLLQTY_NOM_AMT as o_VAL_PASS_FAIL_COLLQTY_NOM_AMT,
	 ( CASE WHEN v_VAL_CHECK_COLLQTY_NOM_AMT = 'F' THEN in_ATTRIBUTE_NAME_COLLQTY_NOM_AMT || ':' || in_ATTRIBUTE_VALUE_COLLQTY_NOM_AMT ELSE NULL END ) as o_ERROR_MESSAGE_COLLQTY_NOM_AMT,
	 ( CASE WHEN v_VAL_CHECK_COLLQTY_NOM_AMT = 'F' THEN v_VALIDATION_SEVERITY_COLLQTY_NOM_AMT ELSE 0 END ) as o_ERROR_SEVERITY_COLLQTY_NOM_AMT,
	 dsf_39.STRING_VALUE as o_VALIDATION_ERROR_CODE_COLLQTY_NOM_AMT,
	 dsf_40.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COLL_NOMINAL_CCY,
	 dsf_41.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLL_NOMINAL_CCY,
	 ( CASE WHEN in_ENABLE_IND_COLL_NOMINAL_CCY = 1 AND v_VALIDATION_ACTIVE_COLL_NOMINAL_CCY = 'Y' THEN ( CASE WHEN COLL_COMP_TYPE = 'SECU' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_NOMINAL_CCY IS NULL THEN 'F' ELSE 'P' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COLL_NOMINAL_CCY,
	 v_VAL_CHECK_COLL_NOMINAL_CCY as o_VAL_PASS_FAIL_COLL_NOMINAL_CCY,
	 ( CASE WHEN v_VAL_CHECK_COLL_NOMINAL_CCY = 'F' THEN in_ATTRIBUTE_NAME_COLL_NOMINAL_CCY || ':' || in_ATTRIBUTE_VALUE_COLL_NOMINAL_CCY ELSE NULL END ) as o_ERROR_MESSAGE_COLL_NOMINAL_CCY,
	 ( CASE WHEN v_VAL_CHECK_COLL_NOMINAL_CCY = 'F' THEN v_VALIDATION_SEVERITY_COLL_NOMINAL_CCY ELSE 0 END ) as o_ERROR_SEVERITY_COLL_NOMINAL_CCY,
	 dsf_42.STRING_VALUE as o_VALIDATION_ERROR_CODE_COLL_NOMINAL_CCY,
	 in_ATTRIBUTE_NAME_COLL_SEC_ID1 as in_ATTRIBUTE_NAME_COLL_SEC_ID1,
