EXP_VAL_CHECK_2Out as (
	/* transType: "Expression" */
Select 
	TRANSACTION_DATE_TIME as TRANSACTION_DATE_TIME,
	 ACTION_TYPE as ACTION_TYPE,
	 COLL_OF_NET_EXPOSURE as COLL_OF_NET_EXPOSURE,
	 MATURITY_DATE as MATURITY_DATE,
	 EXECUTION_TIMESTAMP as EXECUTION_TIMESTAMP,
	 RTRIM ( LTRIM ( REGEXP_REPLACE ( EXECUTION_TIMESTAMP,
	 '[T Z]',
	 ' ',
	 '[^A-Za-z0-9_]',
	 '' ) ) ) as v_EXECUTION_TIMESTAMP,
	 ( CASE WHEN v_EXECUTION_TIMESTAMP IS NULL THEN NULL ELSE TO_DATE ( TO_VARCHAR ( TO_TIMESTAMP ( v_EXECUTION_TIMESTAMP,
	 'YYYY-MM-DD HH24:MI:SS' ),
	 'YYYY-MM-DD' ),
	 'YYYY-MM-DD' ) END ) as v_EXECUTION_TIMESTAMP_date,
	 FIXED_RATE as FIXED_RATE,
	 FLOAT_RATE as FLOAT_RATE,
	 OPEN_TERM as OPEN_TERM,
	 COLL_COMP_TYPE as COLL_COMP_TYPE,
	 COLL_BASKET_ID as COLL_BASKET_ID,
	 PRODUCT as PRODUCT,
	 VALUE_DATE as VALUE_DATE,
	 PRODUCT_TYPE as PRODUCT_TYPE,
	 PRODUCT_SUBTYPE as PRODUCT_SUBTYPE,
	 OTHER_MASTER_AGREEMENT_TYPE as OTHER_MASTER_AGREEMENT_TYPE,
	 in_ATTRIBUTE_NAME_COLL_PRICE_CCY as in_ATTRIBUTE_NAME_COLL_PRICE_CCY,
	 dsf_1.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COLL_PRICE_CCY,
	 dsf_2.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLL_PRICE_CCY,
	 dsf_3.STRING_VALUE as v_VALIDATION_ERROR_CODE_COLL_PRICE_CCY,
	 ( CASE WHEN in_ENABLE_IND_COLL_PRICE_CCY = 1 AND v_VALIDATION_ACTIVE_COLL_PRICE_CCY = 'Y' THEN ( CASE WHEN COLL_COMP_TYPE = 'SECU' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_PRICE_CCY IS NULL THEN 'F' ELSE 'P' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COLL_PRICE_CCY,
	 v_VAL_CHECK_COLL_PRICE_CCY as o_VALIDATION_PASS_FAIL_COLL_PRICE_CCY,
	 ( CASE WHEN v_VAL_CHECK_COLL_PRICE_CCY = 'F' THEN in_ATTRIBUTE_NAME_COLL_PRICE_CCY || ':' || in_ATTRIBUTE_VALUE_COLL_PRICE_CCY ELSE NULL END ) as v_ERROR_MESSAGE_COLL_PRICE_CCY,
	 v_ERROR_MESSAGE_COLL_PRICE_CCY as o_ERROR_MESSAGE_COLL_PRICE_CCY,
	 ( CASE WHEN v_VAL_CHECK_COLL_PRICE_CCY = 'F' THEN v_VALIDATION_SEVERITY_COLL_PRICE_CCY ELSE 0 END ) as o_ERROR_SEVERITY_COLL_PRICE_CCY,
	 v_VALIDATION_ERROR_CODE_COLL_PRICE_CCY as o_VALIDATION_ERROR_CODE_COLL_PRICE_CCY,
	 in_ATTRIBUTE_NAME_COLL_PRICE_PER_UNIT as in_ATTRIBUTE_NAME_COLL_PRICE_PER_UNIT,
	 dsf_4.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COLL_PRICE_PER_UNIT,
	 ( CASE WHEN v_VALIDATION_ACTIVE_COLL_PRICE_PER_UNIT IS NULL THEN 'N' ELSE v_VALIDATION_ACTIVE_COLL_PRICE_PER_UNIT END ) as v_VALIDATION_ACTIVE_NVL_COLL_PRICE_PER_UNIT,
	 dsf_5.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLL_PRICE_PER_UNIT,
	 dsf_6.STRING_VALUE as v_VALIDATION_ERROR_CODE_COLL_PRICE_PER_UNIT,
	 ( CASE WHEN SIGN ( in_ATTRIBUTE_VALUE_COLL_PRICE_PER_UNIT ) > 0 THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_PRICE_PER_UNIT > 999999999999999999 THEN 'F' ELSE 'P' END ) ELSE ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_PRICE_PER_UNIT < -999999999999999999 THEN 'F' ELSE 'P' END ) END ) as v_DECIMAL_CHECK_COLL_PRICE_PER_UNIT,
	 ( CASE WHEN in_ENABLE_IND_COLL_PRICE_PER_UNIT = 1 AND v_VALIDATION_ACTIVE_NVL_COLL_PRICE_PER_UNIT = 'Y' THEN ( CASE WHEN COLL_COMP_TYPE = 'SECU' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_PRICE_PER_UNIT IS NOT NULL AND v_DECIMAL_CHECK_COLL_PRICE_PER_UNIT = 'P' THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COLL_PRICE_PER_UNIT,
	 v_VAL_CHECK_COLL_PRICE_PER_UNIT as o_VALIDATION_PASS_FAIL_COLL_PRICE_PER_UNIT,
	 ( CASE WHEN v_VAL_CHECK_COLL_PRICE_PER_UNIT = 'F' THEN in_ATTRIBUTE_NAME_COLL_PRICE_PER_UNIT || ':' || in_ATTRIBUTE_VALUE_COLL_PRICE_PER_UNIT ELSE NULL END ) as v_ERROR_MESSAGE_COLL_PRICE_PER_UNIT,
	 v_ERROR_MESSAGE_COLL_PRICE_PER_UNIT as o_ERROR_MESSAGE_COLL_PRICE_PER_UNIT,
	 ( CASE WHEN v_VAL_CHECK_COLL_PRICE_PER_UNIT = 'F' THEN v_VALIDATION_SEVERITY_COLL_PRICE_PER_UNIT ELSE 0 END ) as o_ERROR_SEVERITY_COLL_PRICE_PER_UNIT,
	 v_VALIDATION_ERROR_CODE_COLL_PRICE_PER_UNIT as o_VALIDATION_ERROR_CODE_COLL_PRICE_PER_UNIT,
	 in_ATTRIBUTE_NAME_COLL_PRICE_UNIT_SIGN as in_ATTRIBUTE_NAME_COLL_PRICE_UNIT_SIGN,
	 dsf_7.ACTIVE_Y_N as v_VALIDATION_ACTIVECOLL_PRICE_UNIT_SIGN,
	 ( CASE WHEN v_VALIDATION_ACTIVECOLL_PRICE_UNIT_SIGN IS NULL THEN 'N' ELSE v_VALIDATION_ACTIVECOLL_PRICE_UNIT_SIGN END ) as v_VALIDATION_ACTIVE_NVL_COLL_PRICE_UNIT_SIGN,
	 dsf_8.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLL_PRICE_UNIT_SIGN,
	 dsf_9.STRING_VALUE as v_VALIDATION_ERROR_CODE_COLL_PRICE_UNIT_SIGN,
	 ( CASE WHEN in_ENABLE_IND_COLL_PRICE_UNIT_SIGN = 1 AND v_VALIDATION_ACTIVE_NVL_COLL_PRICE_UNIT_SIGN = 'Y' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_PRICE_PER_UNIT IS NOT NULL THEN ( CASE WHEN IN ( in_ATTRIBUTE_VALUE_COLL_PRICE_UNIT_SIGN,
	 'TRUE',
	 'FALSE' ) = 1 THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COLL_PRICE_UNIT_SIGN,
	 v_VAL_CHECK_COLL_PRICE_UNIT_SIGN as o_VALIDATION_PASS_FAIL_COLL_PRICE_UNIT_SIGN,
	 ( CASE WHEN v_VAL_CHECK_COLL_PRICE_UNIT_SIGN = 'F' THEN in_ATTRIBUTE_NAME_COLL_PRICE_UNIT_SIGN || ':' || in_ATTRIBUTE_VALUE_COLL_PRICE_UNIT_SIGN ELSE NULL END ) as v_ERROR_MESSAGE_COLL_PRICE_UNIT_SIGN,
	 v_ERROR_MESSAGE_COLL_PRICE_UNIT_SIGN as o_ERROR_MESSAGE_COLL_PRICE_UNIT_SIGN,
	 ( CASE WHEN v_VAL_CHECK_COLL_PRICE_UNIT_SIGN = 'F' THEN v_VALIDATION_SEVERITY_COLL_PRICE_UNIT_SIGN ELSE 0 END ) as o_ERROR_SEVERITY_COLL_PRICE_UNIT_SIGN,
	 v_VALIDATION_ERROR_CODE_COLL_PRICE_UNIT_SIGN as o_VALIDATION_ERROR_CODE_COLL_PRICE_UNIT_SIGN,
	 in_ATTRIBUTE_NAME_COLL_PRICE_TYP as in_ATTRIBUTE_NAME_COLL_PRICE_TYP,
	 dsf_10.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COLL_PRICE_TYP,
	 dsf_11.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLL_PRICE_TYP,
	 dsf_12.STRING_VALUE as v_VALIDATION_ERROR_CODE_COLL_PRICE_TYP,
	 ( CASE WHEN in_ENABLE_IND_COLL_PRICE_TYP = 1 AND v_VALIDATION_ACTIVE_COLL_PRICE_TYP = 'Y' THEN ( CASE WHEN in_ATTRIBUTE_VALUE_COLL_PRICE_PER_UNIT IS NOT NULL THEN ( CASE WHEN IN ( in_ATTRIBUTE_VALUE_COLL_PRICE_TYP,
	 'PCTG',
	 'YLD',
	 'UNITS' ) = 1 THEN 'P' ELSE 'F' END ) ELSE 'P' END ) ELSE 'P' END ) as v_VAL_CHECK_COLL_PRICE_TYP,
	 v_VAL_CHECK_COLL_PRICE_TYP as o_VALIDATION_PASS_FAIL_COLL_PRICE_TYP,
	 ( CASE WHEN v_VAL_CHECK_COLL_PRICE_TYP = 'F' THEN in_ATTRIBUTE_NAME_COLL_PRICE_TYP || ':' || in_ATTRIBUTE_VALUE_COLL_PRICE_TYP ELSE NULL END ) as v_ERROR_MESSAGE_COLL_PRICE_TYP,
	 v_ERROR_MESSAGE_COLL_PRICE_TYP as o_ERROR_MESSAGE_COLL_PRICE_TYP,
	 ( CASE WHEN v_VAL_CHECK_COLL_PRICE_TYP = 'F' THEN v_VALIDATION_SEVERITY_COLL_PRICE_TYP ELSE 0 END ) as o_ERROR_SEVERITY_COLL_PRICE_TYP,
	 v_VALIDATION_ERROR_CODE_COLL_PRICE_TYP as o_VALIDATION_ERROR_CODE_COLL_PRICE_TYP,
	 in_ATTRIBUTE_NAME_COLL_MARKET_VAL as in_ATTRIBUTE_NAME_COLL_MARKET_VAL,
	 dsf_13.ACTIVE_Y_N as v_VALIDATION_ACTIVE_COLL_MARKET_VAL,
	 dsf_14.NUMBER_VALUE as v_VALIDATION_SEVERITY_COLL_MARKET_VAL,
