	 PRODUCT as PRODUCT,
	 UTI as UTI,
	 COUNTERPARTY as COUNTERPARTY,
	 'ENTITY:' || ENTITY || '/ UTI :' || REPLACE ( REPLACE ( UTI,
	 '|',
	 '*PIPE*' ),
	 '~',
	 '*TILD*' ) || '/ PRODUCT :' || PRODUCT || '/' || 'COUNTERPARTY:' || COUNTERPARTY as v_ERROR_MESSAGE,
