	 ACTION_TYPE_ERROR_SEVERITY as ACTION_TYPE_ERROR_SEVERITY,
	 ACTION_TYPE_ERROR_CODE as ACTION_TYPE_ERROR_CODE,
	 v_ERROR_MESSAGE || '/' || ACTION_TYPE_ERROR_MESSAGE as O_ACTION_TYPE_ERROR_MESSAGE,
