	 SPREAD_VALIDATION_ERROR_CODE as SPREAD_VALIDATION_ERROR_CODE,
	 v_ERROR_MESSAGE || '/' || SPREAD_ERROR_MESSAGE as O_SPREAD_ERROR_MESSAGE,
	 in_ATTRIBUTE_NAME_ACTION_TYPE1 as in_ATTRIBUTE_NAME_ACTION_TYPE1,
	 DECODE ( in_ATTRIBUTE_NAME_ACTION_TYPE1,
	 'ACTION_TYPE1',
	 'ACTION_TYPE',
	 in_ATTRIBUTE_NAME_ACTION_TYPE1 ) as o_ATTRIBUTE_NAME_ACTION_TYPE1,
	 o_VAL_PASS_FAIL_ACTION_TYPE1 as o_VAL_PASS_FAIL_ACTION_TYPE1,
	 o_ERROR_MESSAGE_ACTION_TYPE1 as o_ERROR_MESSAGE_ACTION_TYPE1,
	 o_ERROR_SEVERITY_ACTION_TYPE1 as o_ERROR_SEVERITY_ACTION_TYPE1,
	 o_VALIDATION_ERROR_CODE_ACTION_TYPE1 as o_VALIDATION_ERROR_CODE_ACTION_TYPE1,
	 v_ERROR_MESSAGE || '/' || o_ERROR_MESSAGE_ACTION_TYPE1 as O_ACTION_TYPE1_ERROR_MESSAGE,
