	 VAL_DT_OF_COLL_ERROR_CODE as VAL_DT_OF_COLL_ERROR_CODE,
	 v_ERROR_MESSAGE || '/' || VAL_DT_OF_COLL_ERROR_MESSAGE as O_VAL_DT_OF_COLL_ERROR_MESSAGE,
	 ( CASE WHEN ACTION_TYPE_VALIDATION_PASS_FAIL = 'F' OR SUBMITTING_ENTITY_VALIDATION_PASS_FAIL = 'F' OR REPORTING_CTPTY_VALIDATION_PASS_FAIL = 'F' OR RSPNSBLE_ENTITY_VALIDATION_PASS_FAIL = 'F' OR OTHER_PARTY_VALIDATION_PASS_FAIL = 'F' OR TRIPARTY_AGENT_VALIDATION_PASS_FAIL = 'F' OR CSD_OR_INDIRECT_VALIDATION_PASS_FAIL = 'F' OR COLL_ISSUER_LEI_VALIDATION_PASS_FAIL = 'F' OR COUNTERPARTY_SIDE_VALIDATION_PASS_FAIL = 'F' OR OTHER_PARTY_COUNTRY_VALIDATION_PASS_FAIL = 'F' OR UTI_VALIDATION_PASS_FAIL = 'F' OR EVENT_DATE_VAL_PASS_FAIL = 'F' OR TYPE_OF_SFT_VAL_PASS_FAIL = 'F' OR EXECUTION_TIMESTAMP_VAL_PASS_FAIL = 'F' OR VALUE_DATE_VAL_PASS_FAIL = 'F' OR FIXED_RATE_VAL_PASS_FAIL = 'F' OR PRNCPLE_ON_MAT_DT_VAL_PASS_FAIL = 'F' OR COLL_SEC_ID_VAL_PASS_FAIL = 'F' OR COLL_SEC_CLASSIF_VAL_PASS_FAIL = 'F' OR COLLQTY_NOM_AMT_VAL_PASS_FAIL = 'F' OR COLL_NOMINAL_CCY_VAL_PASS_FAIL = 'F' OR o_VALIDATION_PASS_FAIL_COLL_PRICE_CCY = 'F' OR o_VALIDATION_PASS_FAIL_COLL_PRICE_PER_UNIT = 'F' OR o_VALIDATION_PASS_FAIL_COLL_PRICE_UNIT_SIGN = 'F' OR o_VALIDATION_PASS_FAIL_COLL_PRICE_TYP = 'F' OR o_VAL_PASS_FAIL_COLL_MARKET_VAL = 'F' OR o_VAL_PASS_FAIL_COLL_HAIRCUT_OR_MARGIN = 'F' OR o_VAL_PASS_FAIL_COLL_QUALITY = 'F' OR o_VAL_PASS_FAIL_COLL_SEC_MAT_DT = 'F' OR o_VAL_PASS_FAIL_COLL_ISSUER_JURSDCTN = 'F' OR o_VAL_PASS_FAIL_COLL_TYPE = 'F' OR o_VAL_PASS_FAIL_COLL_REUSE_AVLBLTY = 'F' OR o_VAL_PASS_FAIL_TRADING_VENUE = 'F' OR o_VAL_PASS_FAIL_MASTER_AGRMNT_TYPE = 'F' OR o_VAL_PASS_FAIL_MASTER_AGRMNT_VER = 'F' OR o_VAL_PASS_FAIL_PRNCPLE_ON_VALUE_DT = 'F' OR o_VAL_PASS_FAIL_PRNCPLE_CURR = 'F' OR o_VAL_PASS_FAIL_MATURITY_DATE = 'F' OR o_VAL_PASS_FAIL_TERMINATION_DATE = 'F' OR o_VAL_PASS_FAIL_CSD_OR_INDIRECT_TYPE = 'F' OR o_VALIDATION_PASS_FAIL_COLL_SEC_ID1 = 'F' OR o_VAL_PASS_FAIL_PRNCPLE_ON_VALUE_DT_50 = 'F' OR o_VAL_PASS_FAIL_OTHER_PARTY_VAL51 = 'F' OR FLOAT_RATE_REF_MULT_VALIDATION_PASS_FAIL = 'F' OR FLOAT_RATE_PAYMENT_MULT_VALIDATION_PASS_FAIL = 'F' OR FLOAT_RATE_RESET_MULT_VALIDATION_PASS_FAIL = 'F' OR SPREAD_VALIDATION_PASS_FAIL = 'F' OR o_VAL_PASS_FAIL_ACTION_TYPE1 = 'F' OR VAL_DT_OF_COLL_VALIDATION_PASS_FAIL = 'F' THEN 1 ELSE 0 END ) as v_MD_ERROR_IND,
	 v_MD_ERROR_IND as MD_ERROR_IND,
	 ( CASE WHEN v_ROW_COUNT < '{{ var("FILE_SPLT_CNT") }}' THEN ( CASE WHEN v_MD_ERROR_IND = 0 THEN v_ROW_COUNT + 1 ELSE v_ROW_COUNT END ) ELSE 1 END ) as v_ROW_COUNT,
	 ( CASE WHEN v_ROW_COUNT = 1 AND v_MD_ERROR_IND = 0 THEN v_COUNT + 1 ELSE v_COUNT END ) as v_COUNT,
	 ( CASE WHEN v_MD_ERROR_IND = 0 THEN 'TIUX' || '{{ var("BUSINESS_DATE") }}' || 'X' || TO_VARCHAR ( TO_TIMESTAMP ( '{{ var("BATCH_START_DATE") }}',
